      \u0275\u0275conditionalCreate(308, EmailArchivingContentComponent_Conditional_308_Template, 5, 0, "p");
      \u0275\u0275domElement(309, "hr");
      \u0275\u0275domElementStart(310, "p", 33);
      \u0275\u0275text(311, "An email sent today to or from ");
      \u0275\u0275domElementStart(312, "b");
      \u0275\u0275text(313);
      \u0275\u0275domElementEnd();
      \u0275\u0275text(314);
      \u0275\u0275domElementEnd()()()()();
      \u0275\u0275domElementStart(315, "section", 34)(316, "div", 1)(317, "section", 35)(318, "h2");
      \u0275\u0275text(319, "Compliance and security, built in");
      \u0275\u0275domElementEnd();
      \u0275\u0275domElementStart(320, "p");
      \u0275\u0275text(321, "An archive is only useful if it can be trusted. Every message is encrypted, locked against change and access-controlled, and every action on it is recorded.");
      \u0275\u0275domElementEnd();
      \u0275\u0275domElementStart(322, "div", 36)(323, "article")(324, "i");
      \u0275\u0275text(325, "\u2659");
      \u0275\u0275domElementEnd();
      \u0275\u0275domElementStart(326, "h3");
      \u0275\u0275text(327, "AES-256 & TLS encryption");
      \u0275\u0275domElementEnd();
      \u0275\u0275domElementStart(328, "p");
      \u0275\u0275text(329, "Encrypted at rest with AES-256 and in transit with TLS \u2014 end to end, from journal to archive.");
      \u0275\u0275domElementEnd()();
      \u0275\u0275domElementStart(330, "article")(331, "i");
      \u0275\u0275text(332, "\u2662");
      \u0275\u0275domElementEnd();
      \u0275\u0275domElementStart(333, "h3");
      \u0275\u0275text(334, "Immutable WORM storage");
      \u0275\u0275domElementEnd();
      \u0275\u0275domElementStart(335, "p");
      \u0275\u0275text(336, "Write once, read many: archived messages can\u2019t be changed or deleted before their retention ends.");
      \u0275\u0275domElementEnd()();
      \u0275\u0275domElementStart(337, "article")(338, "i");
      \u0275\u0275text(339, "\u2667");
      \u0275\u0275domElementEnd();
      \u0275\u0275domElementStart(340, "h3");
      \u0275\u0275text(341, "MFA & role-based access");
      \u0275\u0275domElementEnd();
      \u0275\u0275domElementStart(342, "p");
      \u0275\u0275text(343, "Only authorised reviewers can search or export, with MFA and roles you define.");
      \u0275\u0275domElementEnd()();
      \u0275\u0275domElementStart(344, "article")(345, "i");
      \u0275\u0275text(346, "\u25C9");
      \u0275\u0275domElementEnd();
      \u0275\u0275domElementStart(347, "h3");
      \u0275\u0275text(348, "Complete audit trail");
      \u0275\u0275domElementEnd();
      \u0275\u0275domElementStart(349, "p");
      \u0275\u0275text(350, "Every search, view, hold and export is logged \u2014 who, what, when \u2014 for regulators and courts.");
      \u0275\u0275domElementEnd()()();
      \u0275\u0275domElementStart(351, "div", 37)(352, "span");
      \u0275\u0275text(353, "DPDP Act 2023 ");
      \u0275\u0275domElementStart(354, "small");
      \u0275\u0275text(355, "India");
      \u0275\u0275domElementEnd()();
      \u0275\u0275domElementStart(356, "span");
      \u0275\u0275text(357, "IT Act 2000 ");
      \u0275\u0275domElementStart(358, "small");
      \u0275\u0275text(359, "India");
      \u0275\u0275domElementEnd()();
      \u0275\u0275domElementStart(360, "span");
      \u0275\u0275text(361, "SEBI record-keeping ");
      \u0275\u0275domElementStart(362, "small");
      \u0275\u0275text(363, "Broking & markets");
      \u0275\u0275domElementEnd()();
      \u0275\u0275domElementStart(364, "span");
      \u0275\u0275text(365, "RBI directions ");
      \u0275\u0275domElementStart(366, "small");
      \u0275\u0275text(367, "Banks & NBFCs");
      \u0275\u0275domElementEnd()();
      \u0275\u0275domElementStart(368, "span");
      \u0275\u0275text(369, "IRDAI ");
      \u0275\u0275domElementStart(370, "small");
      \u0275\u0275text(371, "Insurance");
      \u0275\u0275domElementEnd()();
      \u0275\u0275domElementStart(372, "span");
      \u0275\u0275text(373, "Companies Act / GST records ");
      \u0275\u0275domElementStart(374, "small");
      \u0275\u0275text(375, "Books & audit");
      \u0275\u0275domElementEnd()();
      \u0275\u0275domElementStart(376, "span");
      \u0275\u0275text(377, "GDPR ");
      \u0275\u0275domElementStart(378, "small");
      \u0275\u0275text(379, "EU clients");
      \u0275\u0275domElementEnd()();
      \u0275\u0275domElementStart(380, "span");
      \u0275\u0275text(381, "HIPAA ");
      \u0275\u0275domElementStart(382, "small");
      \u0275\u0275text(383, "US healthcare");
      \u0275\u0275domElementEnd()();
      \u0275\u0275domElementStart(384, "span");
      \u0275\u0275text(385, "ISO 27001 ");
      \u0275\u0275domElementStart(386, "small");
      \u0275\u0275text(387, "Security");
      \u0275\u0275domElementEnd()();
      \u0275\u0275domElementStart(388, "span");
      \u0275\u0275text(389, "SOC 2 ");
      \u0275\u0275domElementStart(390, "small");
      \u0275\u0275text(391, "Service orgs");
      \u0275\u0275domElementEnd()()()();
      \u0275\u0275domElementStart(392, "p", 38);
      \u0275\u0275text(393, "Archiving supports these frameworks\u2019 retention and evidence requirements; compliance also depends on your own policies and controls. We\u2019ll map retention to the rules that apply to you.");
      \u0275\u0275domElementEnd();
      \u0275\u0275domElementStart(394, "div", 39)(395, "h2");
      \u0275\u0275text(396, "Built for ");
      \u0275\u0275domElementStart(397, "em");
      \u0275\u0275text(398, "how you work");
      \u0275\u0275domElementEnd()()();
      \u0275\u0275domElementStart(399, "div", 40)(400, "article");
      \u0275\u0275domElement(401, "div", 41);
      \u0275\u0275domElementStart(402, "div")(403, "h3");
      \u0275\u0275text(404, "Financial services");
      \u0275\u0275domElementEnd();
      \u0275\u0275domElementStart(405, "p");
      \u0275\u0275text(406, "Retain client communications for SEBI, RBI and IRDAI record-keeping, and answer inspections with an exportable, tamper-proof trail.");
      \u0275\u0275domElementEnd()()();
      \u0275\u0275domElementStart(407, "article");
      \u0275\u0275domElement(408, "div", 42);
      \u0275\u0275domElementStart(409, "div")(410, "h3");
      \u0275\u0275text(411, "Healthcare");
      \u0275\u0275domElementEnd();
      \u0275\u0275domElementStart(412, "p");
      \u0275\u0275text(413, "Keep patient-related communication secure and access-controlled, with retention and audit logs that support DPDP Act and HIPAA obligations.");
      \u0275\u0275domElementEnd()()();
      \u0275\u0275domElementStart(414, "article");
      \u0275\u0275domElement(415, "div", 43);
      \u0275\u0275domElementStart(416, "div")(417, "h3");
      \u0275\u0275text(418, "Education");
      \u0275\u0275domElementEnd();
