      \u0275\u0275domElementStart(263, "li")(264, "b");
      \u0275\u0275text(265, "Email authentication:");
      \u0275\u0275domElementEnd();
      \u0275\u0275text(266, " The recipient's email service validates the message using DMARC, DKIM and SPF, then verifies the CMC to confirm the sender's legitimacy.");
