      \u0275\u0275elementStart(201, "div", 83)(202, "div", 82)(203, "section", 84)(204, "h2", 85);
      \u0275\u0275text(205, "Overview");
      \u0275\u0275elementEnd();
      \u0275\u0275elementStart(206, "p", 86);
      \u0275\u0275text(207, "Microsoft runs the Microsoft 365 service. Your mail, files, sites and chats are yours to protect \u2014 Microsoft's own terms recommend you back them up. Recycle bins and retention policies help with small mistakes, but they sit inside the same tenant, expire on a timer and weren't built to roll a whole user back to before a ransomware attack. XcellHost Microsoft 365 Backup copies Exchange Online, OneDrive, SharePoint and Teams automatically, several times a day, into immutable, encrypted storage outside your tenant. Restore a single email, a folder, a site or an entire user to any point in time \u2014 to the original location, to a new one, or as a download \u2014 without overwriting what's still intact.");
      \u0275\u0275elementEnd()();
      \u0275\u0275elementStart(208, "nav", 87)(209, "a", 88);
      \u0275\u0275text(210, "Coverage");
      \u0275\u0275elementEnd();
