      \u0275\u0275namespaceHTML();
      \u0275\u0275domElementStart(517, "section", 198)(518, "div", 32)(519, "div", 174)(520, "div", 175);
      \u0275\u0275text(521, "Overview");
      \u0275\u0275domElementEnd();
      \u0275\u0275domElementStart(522, "h2");
      \u0275\u0275text(523, "What is Microsoft 365 Frontline?");
      \u0275\u0275domElementEnd();
      \u0275\u0275domElementStart(524, "p");
      \u0275\u0275text(525, "Microsoft\u2019s purpose-built licensing track for the deskless workforce \u2014 communication, basic productivity, shift management and security at a fraction of E-plan cost, in exchange for 2 GB Kiosk mailboxes, no desktop Office install rights and a mandatory E-plan anchor. A 4,000-operator plant on flat E3 costs ~\u20B914.4 cr/yr; the same on F1 + 200 F3 supervisors + 50 E3 managers lands near \u20B91.4 cr \u2014 a 10\xD7 reduction without giving up Walkie-Talkie, Shifts, Tasks, Intune or threat protection.");
      \u0275\u0275domElementEnd()();
