      \u0275\u0275domElementEnd()();
      \u0275\u0275namespaceHTML();
      \u0275\u0275domElementStart(570, "h3");
      \u0275\u0275text(571, "Teams Walkie-Talkie");
      \u0275\u0275domElementEnd();
      \u0275\u0275domElementStart(572, "p");
      \u0275\u0275text(573, "Push-to-talk over Wi-Fi or cellular \u2014 replaces two-way radio fleets across plants, stores, wards and hotels. Channel-based, no spectrum licence, Bluetooth PTT buttons supported.");
      \u0275\u0275domElementEnd()();
      \u0275\u0275domElementStart(574, "div", 215)(575, "span", 216);
      \u0275\u0275namespaceSVG();
      \u0275\u0275domElementStart(576, "svg", 217);
      \u0275\u0275domElement(577, "circle", 202)(578, "path", 203);
      \u0275\u0275domElementEnd()();
