      \u0275\u0275domElementStart(579, "h3");
      \u0275\u0275text(580, "Teams Shifts");
      \u0275\u0275domElementEnd();
      \u0275\u0275domElementStart(581, "p");
      \u0275\u0275text(582, "Digital roster in the Teams app \u2014 managers schedule; workers view, swap, request time off, clock in/out with geofencing. Exports to Darwinbox, Keka, Zoho People, SAP SuccessFactors.");
      \u0275\u0275domElementEnd()();
      \u0275\u0275domElementStart(583, "div", 215)(584, "span", 216);
