      \u0275\u0275domElementStart(589, "p");
      \u0275\u0275text(590, "HQ-published required-task lists on every store/plant/ward tablet; location-specific lists; real-time completion dashboards; photos attach as compliance evidence.");
      \u0275\u0275domElementEnd()();
      \u0275\u0275domElementStart(591, "div", 215)(592, "span", 216);
      \u0275\u0275namespaceSVG();
