      \u0275\u0275text(616, "Viva Connections");
      \u0275\u0275domElementEnd();
      \u0275\u0275domElementStart(617, "p");
      \u0275\u0275text(618, "A single corporate feed inside Teams \u2014 news, role-based dashboards and leadership messages for workers who never open intranet portals.");
