var OUR_PLATFORM_REFERENCE_STYLES = `
:host{
  --navy:#041E42;--navy-2:#0A2A57;--blue:#1565D8;--blue-d:#0C3E8F;--blue-soft:#E8F0FD;
  --orange:#FF8C1A;--orange-d:#F57C00;--ice:#F2F6FC;--white:#fff;
  --ink:#1C2A3A;--slate:#51607A;--line:#DCE5F2;--ok:#2ECC71;--green:#16a34a;
  --disp:"Sora",sans-serif;--body:"IBM Plex Sans",sans-serif;--mono:"IBM Plex Mono",monospace;
  --shadow-s:0 6px 18px rgba(4,30,66,.06);--shadow:0 18px 50px rgba(4,30,66,.10);--shadow-lg:0 34px 80px -20px rgba(4,30,66,.34);
  --maxw:1200px;--ease:cubic-bezier(.22,.7,.2,1);
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{font-family:var(--body);color:var(--ink);background:var(--white);line-height:1.6;overflow-x:hidden;-webkit-font-smoothing:antialiased}
body.lock{overflow:hidden}
h1,h2,h3,h4,h5{font-family:var(--disp);color:var(--navy);line-height:1.12;letter-spacing:-.02em;font-weight:700}
a{color:inherit;text-decoration:none}img,svg{display:block}button{font-family:inherit}
.serif{font-family:'Instrument Serif',serif;font-style:italic;letter-spacing:0}
.wrap{max-width:var(--maxw);margin:0 auto;padding:0 24px}
.mono{font-family:var(--mono)}

#spotlight{position:fixed;inset:0;pointer-events:none;z-index:1;opacity:0;transition:opacity .4s;background:radial-gradient(340px circle at var(--mx,-999px) var(--my,-999px),rgba(21,101,216,.09),transparent 65%)}
#progress{position:fixed;top:0;left:0;height:3px;width:0;z-index:130;background:linear-gradient(90deg,var(--blue),var(--orange));box-shadow:0 0 12px rgba(21,101,216,.6)}

/* buttons */
@keyframes glow{0%,100%{box-shadow:0 10px 26px -10px rgba(255,140,26,.7)}50%{box-shadow:0 14px 34px -8px rgba(255,140,26,.95)}}
.btn{position:relative;display:inline-flex;align-items:center;justify-content:center;gap:9px;overflow:hidden;font-weight:600;font-size:14.5px;padding:12px 22px;border-radius:12px;cursor:pointer;border:1px solid transparent;white-space:nowrap;will-change:transform;transition:transform .18s var(--ease),box-shadow .28s,background .25s,color .25s,border-color .25s}
.btn:before{content:"";position:absolute;top:0;left:-120%;width:60%;height:100%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.45),transparent);transform:skewX(-18deg);transition:left .55s var(--ease)}
.btn:hover:before{left:130%}
.btn-primary{background:var(--orange);color:#fff;animation:glow 2.8s ease-in-out infinite}
.btn-primary:hover{background:#e97a08;transform:translateY(-2px)}
.btn-blue{background:linear-gradient(135deg,var(--blue),var(--blue-d));color:#fff;box-shadow:0 14px 28px -12px rgba(21,101,216,.75)}
.btn-blue:hover{transform:translateY(-2px)}
.btn-orange{background:linear-gradient(135deg,var(--orange),var(--orange-d));color:#fff;box-shadow:0 14px 28px -12px rgba(255,140,26,.7)}
.btn-orange:hover{transform:translateY(-2px)}
.btn-green{background:linear-gradient(135deg,var(--ok),var(--green));color:#fff;box-shadow:0 14px 28px -12px rgba(22,163,74,.6)}
.btn-green:hover{transform:translateY(-2px)}
.btn-goutline{background:#fff;color:var(--green);border:1.5px solid var(--green)}.btn-goutline:hover{background:var(--green);color:#fff}
.btn-ghost{background:#fff;border-color:var(--line);color:var(--navy);box-shadow:var(--shadow-s)}.btn-ghost:hover{border-color:var(--blue);color:var(--blue);transform:translateY(-2px)}
.btn-wa{background:#25D366;color:#fff;border-color:#25D366}.btn-wa:hover{background:#1eb955;border-color:#1eb955;transform:translateY(-2px)}
.btn-dark{background:rgba(255,255,255,.06);color:#fff;border-color:rgba(255,255,255,.28)}.btn-dark:hover{background:rgba(255,255,255,.14);border-color:rgba(255,255,255,.5);transform:translateY(-2px)}
.btn-outline{background:transparent;color:#fff;border-color:rgba(255,255,255,.42)}.btn-outline:hover{background:rgba(255,255,255,.12);transform:translateY(-2px)}
.btn .ar{transition:transform .25s}.btn:hover .ar{transform:translateX(3px)}
.btn-sm{padding:8px 15px;font-size:12.5px}

/* HERO */
.pp-hero{position:relative;overflow:hidden;color:#fff;background:linear-gradient(135deg,#061634 0%,#0c2b63 55%,#12408f 100%);padding:60px 0 72px}
.pp-hero .grid-bg{position:absolute;inset:0;z-index:0;opacity:.5;background-image:linear-gradient(rgba(255,255,255,.06) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.06) 1px,transparent 1px);background-size:48px 48px;mask-image:radial-gradient(760px 560px at 80% 20%,#000,transparent 72%);-webkit-mask-image:radial-gradient(760px 560px at 80% 20%,#000,transparent 72%);animation:gridmove 32s linear infinite}
@keyframes gridmove{to{background-position:48px 48px}}
.aurora{position:absolute;border-radius:50%;filter:blur(70px);z-index:0;pointer-events:none;opacity:.4}
.aurora.a1{width:420px;height:420px;background:radial-gradient(circle,#2f6bff,transparent 65%);top:-100px;right:6%;animation:aflow1 12s ease-in-out infinite}
.aurora.a2{width:340px;height:340px;background:radial-gradient(circle,#ff8c1a,transparent 65%);bottom:-60px;right:26%;animation:aflow2 14s ease-in-out infinite}
@keyframes aflow1{0%,100%{transform:translate(0,0) scale(1)}50%{transform:translate(-30px,24px) scale(1.12)}}
@keyframes aflow2{0%,100%{transform:translate(0,0) scale(1)}50%{transform:translate(26px,-20px) scale(1.15)}}
#net{position:absolute;inset:0;z-index:0;pointer-events:none;opacity:.6}
.pp-hero .wrap{position:relative;z-index:3}
.pp-crumb{font-family:var(--mono);font-size:12px;color:#9fb6de;margin-bottom:22px}.pp-crumb a:hover{color:#fff}.pp-crumb .cur{color:#fff}
.hero-inner{display:grid;grid-template-columns:1.05fr 1fr;gap:44px;align-items:center}
.pp-eyebrow{display:inline-flex;align-items:center;gap:8px;font-family:var(--mono);font-size:11.5px;font-weight:500;letter-spacing:.16em;text-transform:uppercase;color:#bcd4ff;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.16);padding:7px 14px;border-radius:99px}
.pp-eyebrow .dot{width:7px;height:7px;border-radius:50%;background:#5FE08D;animation:cbpulse 2s infinite}
@keyframes cbpulse{0%{box-shadow:0 0 0 0 rgba(95,224,141,.5)}70%{box-shadow:0 0 0 9px rgba(95,224,141,0)}100%{box-shadow:0 0 0 0 rgba(95,224,141,0)}}
.pp-hero h1{color:#fff;font-family:var(--disp);font-size:clamp(17px,3vw,38px);font-weight:800;margin:20px 0 8px;line-height:1.08;white-space:nowrap}
.pp-hero h1 span{font-family:inherit;font-size:inherit;font-style:normal;font-weight:inherit;letter-spacing:inherit}
.pp-hero h1 .brand-line{display:block;font-family:var(--mono);font-size:14px;font-weight:500;letter-spacing:.06em;color:#7fb0ff;margin-bottom:10px;text-transform:none}
.pp-hero h1 .serif{color:#ffd9ac;font-weight:400}
.pp-hero .sub{font-size:16.5px;color:#c9d8f2;max-width:520px;margin:14px 0 22px}
.pp-badges{display:flex;gap:9px;flex-wrap:wrap;margin-bottom:26px}
.pp-badge{display:inline-flex;align-items:center;gap:7px;font-family:var(--mono);font-size:12px;color:#dbe7fb;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.16);padding:7px 13px;border-radius:99px}
.pp-badge svg{width:14px;height:14px;color:#7fb0ff}
.pp-badge.hi{background:rgba(255,140,26,.16);border-color:rgba(255,140,26,.4);color:#ffd9ac}.pp-badge.hi svg{color:#ffb05a}
.hero-cta{display:flex;gap:12px;flex-wrap:wrap;width:650px;max-width:calc(100vw - 48px)}
.hero-cta .btn{padding:12px 20px;border-radius:8px}
.pp-hero .hero-cta .btn-ghost{background:transparent;color:#fff;border-color:rgba(255,255,255,.48);box-shadow:none}
.pp-hero .hero-cta .btn-ghost:hover{background:rgba(255,255,255,.1);color:#fff;border-color:#fff}
.xr{color:#FF3B3B}
.pp-hero h1 .prod{color:#fff}
.hero-lead{font-size:18px;color:#eaf2ff;font-weight:600;margin:16px 0 4px;max-width:540px}
.hero-lead2{font-size:15.5px;color:#c9d8f2;margin-bottom:16px;max-width:540px}
.hero-tech{font-family:var(--disp);font-weight:700;font-size:19px;color:#7fb0ff;margin:6px 0 18px}
.hero-checks{display:grid;grid-template-columns:1fr 1fr;gap:11px 22px;margin-bottom:26px;max-width:540px}
.hero-checks .hc{display:flex;align-items:center;gap:10px;font-size:14.5px;color:#eaf2ff}
.hero-checks .hc .ci{width:22px;height:22px;border-radius:50%;background:var(--blue);display:grid;place-items:center;flex-shrink:0}
.hero-checks .hc .ci svg{width:12px;height:12px;color:#fff}
.powered{position:absolute;left:50%;transform:translateX(-50%);bottom:-16px;z-index:6;background:#fff;border-radius:14px;padding:11px 22px;box-shadow:var(--shadow-lg);text-align:center}
.powered small{font-family:var(--mono);font-size:9.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--slate);display:block;margin-bottom:3px}
.powered b{font-family:var(--disp);font-size:20px;color:var(--navy)}.powered b span{color:#FF6A00}
.dc-seal{display:inline-flex;align-items:center;gap:9px;background:linear-gradient(155deg,#f4f9fd,#dcecf9 62%,#cbe1f4);border:1px solid #c6dcef;border-radius:10px;padding:8px 26px 8px 11px;position:relative;box-shadow:0 10px 22px -12px rgba(4,30,66,.4)}
.dc-seal .dc-ic{width:36px;height:36px;flex-shrink:0}
.dc-seal .dc-txt{display:flex;flex-direction:column;line-height:1.05;text-align:left}
.dc-seal .dc-word{font-family:var(--disp);font-weight:800;font-size:18px;color:#123f6b;letter-spacing:-.01em}
.dc-seal .dc-word sup{font-size:8px;position:relative;top:-.85em;color:#5f83a6}
.dc-seal .dc-verified{font-family:var(--mono);font-size:8.5px;letter-spacing:.24em;color:#5f83a6;margin-top:3px}
.dc-seal .dc-info{position:absolute;top:5px;right:7px;width:12px;height:12px;border-radius:50%;border:1px solid #a6bcd2;color:#7f98b2;font-size:8px;display:grid;place-items:center;font-family:Georgia,serif;font-style:italic}
.dc-seal.sm{padding:6px 22px 6px 9px;gap:7px}.dc-seal.sm .dc-ic{width:28px;height:28px}.dc-seal.sm .dc-word{font-size:14px}.dc-seal.sm .dc-verified{font-size:7.5px}
.dc-date{font-family:var(--mono);font-size:8.5px;color:#8aa2bd;display:block;margin-top:5px}
.sl-logo{display:inline-flex;align-items:center;gap:8px}
.sl-logo .sl-mark{width:26px;height:26px;flex-shrink:0}
.sl-logo .sl-word{font-family:var(--disp);font-weight:800;font-size:20px;letter-spacing:-.01em;line-height:1;color:var(--navy)}
.sl-logo.light .sl-word{color:#fff}
.sl-logo.sm .sl-mark{width:20px;height:20px}.sl-logo.sm .sl-word{font-size:15px}
.mail{position:relative;background:#fff;border-radius:16px;box-shadow:var(--shadow-lg);overflow:hidden;width:100%}
.mail-bar{display:flex;align-items:center;gap:12px;padding:12px 16px;background:#f3f6fc;border-bottom:1px solid var(--line)}
.mail-bar .dots{display:flex;gap:6px}.mail-bar .dots i{width:10px;height:10px;border-radius:50%;background:#d3ddef}
.mail-title{font-family:var(--mono);font-size:12px;color:var(--slate);letter-spacing:.05em}
.mail-body{position:relative;padding:14px;display:flex;flex-direction:column;gap:10px;background:#fff}
.mrow{display:flex;align-items:center;gap:12px;padding:11px 12px;border-radius:12px;background:#fff;border:1px solid var(--line)}
.mrow.hot{border-color:#bcd3f7;box-shadow:0 10px 24px -14px rgba(21,101,216,.65);background:linear-gradient(90deg,#f5f9ff,#fff)}
.mav{width:38px;height:38px;border-radius:50%;flex-shrink:0;display:grid;place-items:center;font-family:var(--disp);font-weight:800;color:#fff;font-size:15px}
.mrow.hot .mav{background:linear-gradient(135deg,var(--blue),var(--navy))}.mav svg{width:20px;height:20px;color:#fff}
.mav.g1{background:#f0a53a}.mav.g2{background:#57a94a}
.mtx{min-width:0}.mtx b{font-family:var(--disp);font-size:14px;color:var(--navy);display:flex;align-items:center;gap:6px}
.mtx>span{font-size:12px;color:var(--slate);display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:210px}
.vck{width:16px;height:16px;border-radius:50%;background:var(--blue);display:inline-grid;place-items:center}.vck svg{width:10px;height:10px;color:#fff}
.prov-strip{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin:2px 0 30px}
.prov-lbl{font-family:var(--mono);font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:var(--slate);margin-right:4px}
.prov{font-family:var(--disp);font-weight:700;font-size:14px;color:var(--navy);background:#fff;border:1px solid var(--line);border-radius:9px;padding:8px 16px;box-shadow:0 4px 12px -8px rgba(4,18,42,.4)}
.prov.logo{display:inline-flex;align-items:center;gap:8px;padding:7px 15px 7px 8px}
.prov.logo .pl{width:24px;height:24px;border-radius:6px;display:grid;place-items:center;color:#fff;flex-shrink:0}
.prov.logo .pl svg{width:15px;height:15px}
/* engagement before/after */
.eng-grid{display:grid;grid-template-columns:1fr 1fr;gap:44px;align-items:center;margin-top:6px}
.eng-copy p{color:var(--slate);font-size:15px;line-height:1.7;margin-bottom:14px}
.eng-stats{display:flex;gap:14px;margin-top:20px;flex-wrap:wrap}
.eng-stat{background:var(--blue-soft);border:1px solid #cfe0fb;border-radius:14px;padding:14px 18px;min-width:132px}
.eng-stat b{display:block;font-family:var(--disp);font-weight:800;font-size:26px;color:var(--blue);line-height:1}
.eng-stat span{font-size:12.5px;color:var(--slate)}
.eng-visual{display:flex;align-items:center;justify-content:center;gap:6px}
.phone{position:relative;width:186px;flex:0 0 186px;background:#0e1b33;border-radius:30px;padding:9px;box-shadow:0 30px 60px -24px rgba(4,18,42,.55)}
.phone .screen{background:#f4f7fb;border-radius:22px;overflow:hidden;position:relative;height:340px}
.phone .notch{position:absolute;top:8px;left:50%;transform:translateX(-50%);width:52px;height:5px;border-radius:6px;background:rgba(255,255,255,.5);z-index:3}
.ph-top{background:#fff;padding:16px 12px 10px;border-bottom:1px solid var(--line)}
.ph-search{background:#eef2f9;border-radius:20px;height:26px;display:flex;align-items:center;padding:0 12px;font-size:10px;color:#9aa8c0;font-family:var(--body)}
.ph-lbl{font-family:var(--mono);font-size:8px;letter-spacing:.14em;color:#b7c2d6;padding:8px 12px 2px;text-transform:uppercase}
.pmrow{display:flex;align-items:center;gap:9px;padding:8px 12px}
.pav{width:26px;height:26px;border-radius:50%;flex-shrink:0;display:grid;place-items:center;font-family:var(--disp);font-weight:800;font-size:11px;color:#fff}
.pav.gen{background:#c3ccdb}
.pav.b1{background:linear-gradient(135deg,#1565D8,#0C3E8F)}.pav.b2{background:linear-gradient(135deg,#FF8C1A,#F57C00)}.pav.b3{background:linear-gradient(135deg,#16a34a,#12823a)}.pav.b4{background:linear-gradient(135deg,#0A2A57,#1565D8)}
.pav svg{width:15px;height:15px;color:#fff}
.pmtx{min-width:0;flex:1}
.pmtx b{font-family:var(--disp);font-size:11px;color:var(--navy);display:flex;align-items:center;gap:4px;line-height:1.2}
.pmtx span{display:block;font-size:9px;color:#8391a8;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pvck{width:12px;height:12px;border-radius:50%;background:var(--blue);display:inline-grid;place-items:center;flex-shrink:0}
.pvck svg{width:8px;height:8px;color:#fff}
.phone .cap{position:absolute;left:0;right:0;bottom:-30px;text-align:center;font-family:var(--mono);font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:var(--slate)}
.phone.after{box-shadow:0 30px 60px -20px rgba(21,101,216,.6)}
.phone.after .cap{color:var(--blue)}
.eng-arrows{display:flex;gap:1px;color:var(--blue);flex:0 0 auto}
.eng-arrows svg{width:16px;height:26px;opacity:.35;animation:engflow 1.4s infinite}
.eng-arrows svg:nth-child(2){animation-delay:.2s}.eng-arrows svg:nth-child(3){animation-delay:.4s}
@keyframes engflow{0%,100%{opacity:.25}50%{opacity:1}}
.pmrow.pop .pav,.pmrow.pop .pvck{animation:tickpop .5s both}
@media(max-width:900px){.eng-grid{grid-template-columns:1fr;gap:34px}.eng-visual{gap:2px}.phone{width:160px;flex-basis:160px}}
@media(max-width:420px){.phone{width:140px;flex-basis:140px}.eng-arrows svg{width:12px}}
/* hero visual */
.ssl-stage{position:relative;min-height:380px;display:flex;align-items:center;justify-content:center}
.orbit-ring{position:absolute;inset:6% 8%;border:1.5px dashed rgba(127,176,255,.3);border-radius:50%;z-index:0;animation:orbit 40s linear infinite}
.orbit-ring:after{content:"";position:absolute;top:-5px;left:50%;width:9px;height:9px;border-radius:50%;background:var(--orange);box-shadow:0 0 12px var(--orange)}
@keyframes orbit{to{transform:rotate(360deg)}}
.browser{position:relative;z-index:2;width:100%;max-width:430px;background:#fff;border-radius:18px;box-shadow:var(--shadow-lg);overflow:hidden;animation:scfloat 6s ease-in-out infinite}
@keyframes scfloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-11px)}}
.browser .bar{display:flex;align-items:center;gap:8px;padding:11px 14px;background:var(--ice);border-bottom:1px solid var(--line)}
.browser .dots{display:flex;gap:5px}.browser .dots i{width:9px;height:9px;border-radius:50%;background:#cdd8ea;display:block}
.browser .url{flex:1;display:flex;align-items:center;gap:7px;background:#fff;border:1px solid var(--line);border-radius:8px;padding:6px 10px;font-family:var(--mono);font-size:11px;color:var(--navy)}
.browser .url .lock{color:var(--green)}.browser .url .lock svg{width:12px;height:12px}.browser .url b{color:var(--green)}
.browser .body{position:relative;height:220px;background:linear-gradient(160deg,#08163a,#123776 60%,#1c56c8);overflow:hidden}
.browser .body .scanline{position:absolute;left:0;right:0;height:100px;background:linear-gradient(180deg,transparent,rgba(90,150,255,.28),transparent);animation:pphscan 4.5s var(--ease) infinite}
@keyframes pphscan{0%{top:-100px}100%{top:100%}}
.seal{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:126px;height:126px}
.seal .ring{animation:orbit 24s linear infinite;transform-origin:63px 63px}
.seal .lens-glow{animation:lensGlow 2.4s ease-in-out infinite}@keyframes lensGlow{0%,100%{opacity:.55}50%{opacity:1}}
.float-card{position:absolute;background:#fff;border-radius:13px;box-shadow:var(--shadow);padding:11px 14px;z-index:4;display:flex;align-items:center;gap:10px}
.float-card .fi{width:32px;height:32px;border-radius:9px;display:grid;place-items:center;flex-shrink:0}.float-card .fi svg{width:17px;height:17px}
.float-card b{font-family:var(--disp);font-size:13px;color:var(--navy);display:block;line-height:1.2}.float-card span{font-family:var(--mono);font-size:10px;color:var(--slate)}
.fc-secured{left:-16px;top:-30px;bottom:auto;animation:scfloat 7s ease-in-out infinite}.fc-secured .fi{background:#e4f7ec;color:var(--green)}
.fc-warranty{right:-26px;bottom:12%;animation:scfloat 8s ease-in-out infinite}.fc-warranty .fi{background:var(--blue-soft);color:var(--blue)}
.fc-issued{right:-26px;top:2%;animation:scfloat 6.5s ease-in-out infinite}.fc-issued .fi{background:#fff3e0;color:var(--orange)}

/* trust strip */
.pp-trust{background:var(--ice);border-bottom:1px solid var(--line)}
.pp-trust .wrap{display:flex;justify-content:space-between;align-items:center;gap:18px;flex-wrap:wrap;padding:20px 24px;font-size:13px;color:var(--slate);font-weight:500}
.pp-trust b{color:var(--navy);font-family:var(--mono)}

/* body + section titles */
.pp-body{padding:52px 0 56px}
.pp-sec{font:700 15px/1.35 var(--mono);letter-spacing:.14em;text-transform:uppercase;color:var(--blue);margin:52px 0 16px}
.pp-sec:first-child{margin-top:0}
.pp-ov{font-size:16.5px;color:var(--ink);line-height:1.75;max-width:none}.pp-ov+.pp-ov{margin-top:14px}.pp-ov b{color:var(--navy)}

/* validation levels */
.pp-vgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:8px}
.vcard{background:#fff;border:1px solid var(--line);border-radius:18px;padding:26px;box-shadow:var(--shadow-s);transition:.3s var(--ease)}
.vcard:hover{transform:translateY(-6px);box-shadow:var(--shadow);border-color:#c9dcfb}
.vcard .vb{display:inline-flex;align-items:center;gap:7px;font-family:var(--mono);font-size:12px;font-weight:600;padding:6px 12px;border-radius:99px;margin-bottom:16px}
.vcard.dv .vb{background:var(--blue-soft);color:var(--blue)}.vcard.ov .vb{background:#eaeff9;color:#2b4a8f}.vcard.ev .vb{background:#fff3e0;color:var(--orange-d)}
.vcard .vb svg{width:14px;height:14px}
.vcard h3{font-size:18px;margin-bottom:8px}.vcard p{font-size:13.5px;color:var(--slate);margin-bottom:16px}
.vcard ul{list-style:none;display:flex;flex-direction:column;gap:9px}
.vcard li{display:flex;gap:9px;font-size:13px;color:var(--ink)}
.vcard li .ck,.pfeat li .ck{width:17px;height:17px;border-radius:50%;background:#e4f7ec;color:var(--green);display:grid;place-items:center;flex-shrink:0;margin-top:2px}
.vcard li .ck svg,.pfeat li .ck svg{width:10px;height:10px}

/* product catalog + cart */
.filter{display:flex;gap:10px;flex-wrap:wrap;margin:8px 0 26px}
.fchip{font-family:var(--mono);font-size:12.5px;font-weight:500;color:var(--slate);background:#fff;border:1px solid var(--line);padding:9px 18px;border-radius:99px;cursor:pointer;transition:.22s var(--ease)}
.fchip:hover{border-color:var(--blue);color:var(--blue)}
.fchip.on{background:linear-gradient(135deg,var(--blue),var(--blue-d));color:#fff;border-color:transparent;box-shadow:0 10px 22px -10px rgba(21,101,216,.7)}
.pgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.pcard{background:#fff;border:1px solid var(--line);border-radius:18px;padding:22px;box-shadow:var(--shadow-s);display:flex;flex-direction:column;transition:.3s var(--ease);position:relative;overflow:hidden}
.pcard:before{content:"";position:absolute;left:0;top:0;right:0;height:3px;background:linear-gradient(90deg,var(--blue),var(--orange));transform:scaleX(0);transform-origin:left;transition:.35s var(--ease)}
.pcard:hover{transform:translateY(-6px);box-shadow:var(--shadow-lg);border-color:#c9dcfb}.pcard:hover:before{transform:scaleX(1)}
.pcard .ptop{display:flex;align-items:center;gap:8px;margin-bottom:12px;flex-wrap:wrap}
.tierbadge{font-family:var(--mono);font-size:10.5px;font-weight:600;padding:4px 10px;border-radius:99px}
.tierbadge.dv{background:var(--blue-soft);color:var(--blue)}.tierbadge.ov{background:#eaeff9;color:#2b4a8f}.tierbadge.ev{background:#fff3e0;color:var(--orange-d)}
.tierbadge.find{background:var(--blue-soft);color:var(--blue)}.tierbadge.fix{background:#fff3e0;color:var(--orange-d)}.tierbadge.prevent{background:#e8f7ee;color:var(--green)}
.tagchip{font-family:var(--mono);font-size:10px;color:var(--slate);background:var(--ice);border:1px solid var(--line);padding:4px 9px;border-radius:99px}
.pcard h3{font-size:16px;margin-bottom:6px;min-height:42px}
.pcard .pdesc{font-size:12.5px;color:var(--slate);margin-bottom:12px;min-height:34px}
.pmeta{display:flex;gap:16px;margin-bottom:12px;font-size:11.5px}
.pmeta span{color:var(--slate);display:block}.pmeta b{font-family:var(--disp);font-size:13px;color:var(--navy)}
.pfeat{list-style:none;display:flex;flex-direction:column;gap:7px;margin-bottom:16px}
.pfeat li{display:flex;gap:9px;font-size:12.5px;color:var(--ink)}
.pprice{margin-top:auto;padding-top:14px;border-top:1px solid var(--line);display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:14px}
.pprice .from{font-size:11px;color:var(--slate);display:block}.pprice .amt{font-family:var(--disp);font-size:23px;font-weight:800;color:var(--navy)}
.pprice .yr{font-family:var(--mono);font-size:11px;color:var(--slate)}
.pprice .save{font-family:var(--mono);font-size:11px;font-weight:600;color:var(--green);background:#e4f7ec;padding:4px 9px;border-radius:99px}
.pcard .btn{width:100%}
.pv-note{margin-top:16px;font-size:13px;color:var(--slate);font-family:var(--mono)}
.pgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:6px 0}
.pcard.hot{border-color:var(--orange);box-shadow:0 20px 44px -20px rgba(255,140,26,.55)}
.tagchip.best{background:#fff3e0;color:var(--orange-d);border-color:#ffd9a8;font-weight:700}
@media(max-width:900px){.pgrid{grid-template-columns:1fr}}
.plans{display:grid;grid-template-columns:repeat(3,1fr);gap:0;border-radius:16px;overflow:hidden;box-shadow:var(--shadow-lg);margin:6px 0 6px}
.plan{display:flex;flex-direction:column;background:#fff}
.plan-head{padding:20px 16px;text-align:center;color:#fff}
.plan-head .pbag{width:32px;height:32px;display:block;margin:0 auto 8px;color:#fff}
.plan-head b{font-family:var(--disp);font-weight:800;font-size:22px}
.plan-basic .plan-head{background:#2f3178}
.plan-pro .plan-head{background:#e97c1e}
.plan-business .plan-head{background:#54a24a}
.plan-body{padding:26px 24px 30px;flex:1;display:flex;flex-direction:column}
.plan-basic .plan-body{background:#ececf4}
.plan-pro .plan-body{background:#fcefe1}
.plan-business .plan-body{background:#e9f6ea}
.plan-price{font-family:var(--disp);font-weight:800;font-size:30px;color:var(--navy);text-align:center;line-height:1}
.plan-price span{font-size:16px;font-weight:700;color:var(--slate)}
.plan-billed{text-align:center;font-size:12.5px;font-style:italic;color:var(--slate);margin-top:8px}
.plan-plus{font-weight:700;color:var(--ink);font-size:14px;margin:22px 0 14px}
.plan-basic .plan-feats{margin-top:30px}
.plan-feats{list-style:none;display:flex;flex-direction:column;gap:13px;margin-bottom:24px}
.plan-feats li{display:flex;align-items:flex-start;gap:9px;font-size:14px;color:var(--ink)}
.plan-feats li svg{width:15px;height:15px;color:var(--green);flex-shrink:0;margin-top:3px}
.plan-buy{margin-top:auto;align-self:center;padding:10px 26px;border-radius:8px;background:#fff;border:2px solid;font-family:var(--body);font-weight:700;font-size:15px;cursor:pointer;transition:.18s}
.plan-basic .plan-buy{color:#2f3178;border-color:#2f3178}.plan-basic .plan-buy:hover{background:#2f3178;color:#fff}
.plan-pro .plan-buy{color:#e97c1e;border-color:#e97c1e}.plan-pro .plan-buy:hover{background:#e97c1e;color:#fff}
.plan-business .plan-buy{color:#54a24a;border-color:#54a24a}.plan-business .plan-buy:hover{background:#54a24a;color:#fff}
@media(max-width:820px){.plans{grid-template-columns:1fr}.plan-basic .plan-feats{margin-top:14px}}

/* comparison table */
.pp-tablewrap{overflow-x:auto;border:1px solid var(--line);border-radius:14px;background:#fff;margin-top:8px}
.pp-table{width:100%;border-collapse:collapse;min-width:640px}
.pp-table th{background:var(--ice);font:600 11.5px var(--mono);letter-spacing:.1em;text-transform:uppercase;color:var(--slate);text-align:left;padding:14px 18px;border-bottom:1px solid var(--line)}
.pp-table th:not(:first-child){text-align:center}
.pp-table td{padding:13px 18px;border-bottom:1px solid var(--line);font-size:13.5px;color:var(--ink)}
.pp-table td:not(:first-child){text-align:center}
.pp-table tr:last-child td{border-bottom:none}
.pp-table td:first-child{font-weight:600;color:var(--navy)}
.pp-table .yes{color:var(--green);font-weight:700}.pp-table .no{color:#c3ccdb}
.pp-table thead th:nth-child(4){color:var(--orange-d)}

/* add-ons */
.pp-addons{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-top:8px}
.pp-addon{border:1px solid var(--line);border-radius:12px;padding:18px;background:#fff;transition:.2s var(--ease)}
.pp-addon:hover{border-color:var(--blue);box-shadow:0 8px 20px rgba(21,101,216,.08);transform:translateY(-4px)}
.pp-addon .aic{width:34px;height:34px;border-radius:9px;background:var(--blue-soft);color:var(--blue);display:grid;place-items:center;margin-bottom:10px}.pp-addon .aic svg{width:18px;height:18px}
.pp-addon b{display:block;font-family:var(--disp);font-size:14px;color:var(--navy);margin-bottom:4px}
.pp-addon p{font-size:12.5px;color:var(--slate);line-height:1.5}

/* features */
.pp-feats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:8px}
.pp-feat{border:1px solid var(--line);border-radius:12px;padding:18px 20px;display:flex;gap:14px;align-items:flex-start;transition:.2s var(--ease);background:#fff}
.pp-feat:hover{border-color:var(--blue);box-shadow:0 8px 22px rgba(21,101,216,.1);transform:translateY(-4px)}
.pp-feat .fic{flex:none;width:38px;height:38px;border-radius:10px;display:grid;place-items:center;color:#fff}
.pp-feat .fic svg{width:19px;height:19px}
.pp-feat b{font-family:var(--disp);font-size:14.5px;color:var(--navy);display:block;margin-bottom:3px}
.pp-feat p{font-size:12.7px;color:var(--slate);line-height:1.5}

/* benefits */
.pp-bens{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-top:8px}
.pb{border:1px solid var(--line);border-radius:12px;padding:18px;background:#fff;transition:.2s var(--ease)}
.pb:hover{border-color:var(--blue);box-shadow:var(--shadow-s);transform:translateY(-4px)}
.pb .ic{width:40px;height:40px;border-radius:11px;background:var(--blue-soft);color:var(--blue);display:grid;place-items:center;margin-bottom:12px}.pb .ic svg{width:20px;height:20px}
.pb b{font-family:var(--disp);font-size:14px;color:var(--navy);display:block;margin-bottom:4px}.pb p{font-size:12.5px;color:var(--slate);line-height:1.5}

/* automation panel */
.pp-auto{margin-top:16px;background:linear-gradient(120deg,var(--navy),#123776 60%,var(--blue));border-radius:20px;padding:34px;color:#fff;position:relative;overflow:hidden;display:grid;grid-template-columns:1.2fr 1fr;gap:30px;align-items:center;box-shadow:var(--shadow-lg)}
.pp-auto:before{content:"";position:absolute;inset:0;opacity:.5;background-image:linear-gradient(rgba(255,255,255,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.05) 1px,transparent 1px);background-size:34px 34px;animation:gridmove 30s linear infinite}
.pp-auto .glow{position:absolute;width:280px;height:280px;border-radius:50%;background:radial-gradient(circle,rgba(255,140,26,.4),transparent 65%);filter:blur(30px);right:-40px;top:-60px;animation:aflow2 12s ease-in-out infinite}
.pp-auto .al{position:relative;z-index:2}
.pp-auto .tag{display:inline-flex;align-items:center;gap:7px;font-family:var(--mono);font-size:11.5px;letter-spacing:.14em;text-transform:uppercase;color:#ffd9ac;background:rgba(255,140,26,.16);border:1px solid rgba(255,140,26,.35);padding:6px 12px;border-radius:99px;margin-bottom:14px}
.pp-auto h3{color:#fff;font-size:24px;margin-bottom:10px}
.pp-auto p{color:#c9d8f2;font-size:14.5px;margin-bottom:16px;max-width:46ch}
.pp-auto ul{list-style:none;display:grid;grid-template-columns:1fr 1fr;gap:9px}
.pp-auto li{display:flex;gap:8px;font-size:13px;color:#e7eefb}
.pp-auto li .k{color:#5FE08D;flex:none}
.pp-auto .ar-visual{position:relative;z-index:2;display:flex;flex-direction:column;gap:10px}
.ar-step{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.14);border-radius:12px;padding:12px 14px;display:flex;align-items:center;gap:12px;font-size:13px;color:#fff}
.ar-step .n{width:26px;height:26px;border-radius:8px;background:var(--orange);color:#fff;display:grid;place-items:center;font-family:var(--disp);font-weight:700;font-size:13px;flex-shrink:0}
.ar-step.done .n{background:var(--ok)}

/* use cases */
.pp-uses{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-top:8px}
.pu{border:1px solid var(--line);border-radius:12px;padding:18px;background:#fff;transition:.2s var(--ease)}
.pu:hover{border-color:var(--blue);box-shadow:var(--shadow-s);transform:translateY(-4px)}
.pu-ic{width:40px;height:40px;border-radius:11px;background:var(--ice);display:grid;place-items:center;font-size:20px;margin-bottom:12px}
.pu b{font-family:var(--disp);font-size:14px;color:var(--navy);display:block;margin-bottom:3px}.pu span{font-size:12.3px;color:var(--slate)}

/* security rows */
.pp-secrows{display:grid;grid-template-columns:repeat(2,1fr);gap:0 34px;margin-top:8px}
.psr{display:flex;gap:13px;padding:16px 0;border-bottom:1px solid var(--line)}
.psr .si{width:38px;height:38px;border-radius:10px;background:var(--blue-soft);color:var(--blue);display:grid;place-items:center;flex-shrink:0}.psr .si svg{width:19px;height:19px}
.psr b{font-family:var(--disp);font-size:14.5px;color:var(--navy);display:block;margin-bottom:3px}.psr p{font-size:12.7px;color:var(--slate);line-height:1.5}

/* why */
.pp-why{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:8px}
.pw{border:1px solid var(--line);border-radius:12px;padding:20px;background:#fff;transition:.2s var(--ease)}
.pw:hover{border-color:var(--blue);box-shadow:var(--shadow-s);transform:translateY(-4px)}
.pw-ic{width:42px;height:42px;border-radius:11px;background:linear-gradient(135deg,var(--blue),var(--blue-d));color:#fff;display:grid;place-items:center;margin-bottom:12px}.pw-ic svg{width:21px;height:21px}
.pw b{font-family:var(--disp);font-size:14.5px;color:var(--navy);display:block;margin-bottom:4px}.pw p{font-size:12.7px;color:var(--slate);line-height:1.5}

/* modal + cart + toast */
.overlay{position:fixed;inset:0;z-index:200;background:rgba(4,18,42,.55);backdrop-filter:blur(4px);opacity:0;visibility:hidden;transition:opacity .3s,visibility .3s}
.overlay.open{opacity:1;visibility:visible}
.modal{position:fixed;left:50%;top:50%;z-index:210;width:min(860px,94vw);max-height:92vh;transform:translate(-50%,-46%);opacity:0;visibility:hidden;background:#fff;border-radius:20px;overflow:hidden;box-shadow:0 50px 120px -30px rgba(4,18,42,.6);transition:opacity .32s var(--ease),transform .32s var(--ease),visibility .32s;display:flex;flex-direction:column}
.modal.open{opacity:1;visibility:visible;transform:translate(-50%,-50%)}
.modal-head{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:20px 26px;background:linear-gradient(120deg,var(--orange),var(--orange-d));color:#fff}
.modal-head h3{color:#fff;font-size:20px}
.modal-close{width:38px;height:38px;border-radius:11px;border:0;background:rgba(255,255,255,.18);color:#fff;cursor:pointer;display:grid;place-items:center;transition:.2s;flex-shrink:0}.modal-close:hover{background:rgba(255,255,255,.32);transform:rotate(90deg)}.modal-close svg{width:18px;height:18px}
.modal-body{display:grid;grid-template-columns:1.35fr 1fr;gap:24px;padding:24px 26px;overflow-y:auto}
.terms{display:flex;flex-direction:column;gap:12px}
.term{position:relative;display:flex;gap:13px;align-items:flex-start;padding:15px 16px;border:1.5px solid var(--line);border-radius:14px;cursor:pointer;transition:.2s var(--ease);background:#fff}
.term:hover{border-color:#c9dcfb;background:#fbfcff}.term.sel{border-color:var(--blue);background:var(--blue-soft)}
.term .radio{width:20px;height:20px;border-radius:50%;border:2px solid #b9c6dd;flex-shrink:0;margin-top:2px;position:relative;transition:.2s}
.term.sel .radio{border-color:var(--blue)}.term.sel .radio:after{content:"";position:absolute;inset:3px;border-radius:50%;background:var(--blue)}
.term .tinfo b{font-family:var(--disp);font-size:15px;color:var(--navy)}
.term .tsub{font-family:var(--mono);font-size:11.5px;color:var(--slate);margin-top:3px;line-height:1.5}
.term .tsub .list{text-decoration:line-through;color:#9aa8c2}.term .tsub .sv{color:var(--green);font-weight:600}.term .tsub .off{color:var(--orange-d);font-weight:600}
.term .best{position:absolute;right:0;top:14px;background:linear-gradient(135deg,var(--orange),var(--orange-d));color:#fff;font-family:var(--mono);font-size:9.5px;font-weight:600;padding:5px 12px 5px 14px;border-radius:99px 0 0 99px}
.config{display:flex;flex-direction:column}
.gt-logo{display:flex;align-items:center;gap:9px;justify-content:flex-end;margin-bottom:20px}
.gt-logo .seal-sm{width:30px;height:30px;border-radius:8px;background:linear-gradient(135deg,var(--orange),var(--orange-d));display:grid;place-items:center;color:#fff}.gt-logo .seal-sm svg{width:17px;height:17px}
.gt-logo b{font-family:var(--disp);font-size:20px;color:var(--navy)}
.cfg-row{margin-bottom:16px}.cfg-row label{display:flex;align-items:center;gap:6px;font-size:13px;font-weight:600;color:var(--navy);margin-bottom:8px}
.cfg-row .q{width:16px;height:16px;border-radius:50%;background:var(--blue-soft);color:var(--blue);display:grid;place-items:center;font-size:10px;font-weight:700;cursor:help;font-family:var(--mono)}
.stepper{display:flex;align-items:center;justify-content:space-between;gap:10px}.stepper .san-price{font-family:var(--mono);font-size:12px;color:var(--slate)}
.stepper .ctrl{display:flex;align-items:center;border:1px solid var(--line);border-radius:10px;overflow:hidden}
.stepper .ctrl button{width:32px;height:34px;border:0;background:#fff;color:var(--navy);font-size:17px;cursor:pointer;transition:.15s}.stepper .ctrl button:hover{background:var(--blue-soft);color:var(--blue)}
.stepper .ctrl input{width:42px;height:34px;border:0;border-left:1px solid var(--line);border-right:1px solid var(--line);text-align:center;font-family:var(--mono);font-size:14px;color:var(--navy);-moz-appearance:textfield}
.stepper .ctrl input::-webkit-outer-spin-button,.stepper .ctrl input::-webkit-inner-spin-button{-webkit-appearance:none;margin:0}
.cfg-line{display:flex;justify-content:space-between;align-items:center;padding:12px 0;border-top:1px solid var(--line);font-size:13.5px;color:var(--slate)}.cfg-line b{font-family:var(--disp);color:var(--navy)}
.total-line{display:flex;justify-content:space-between;align-items:baseline;padding:14px 0;border-top:2px solid var(--line)}.total-line span{font-family:var(--disp);font-size:15px;font-weight:600;color:var(--navy)}.total-line b{font-family:var(--disp);font-size:28px;font-weight:800;color:var(--navy)}
.gsttag{font-family:var(--mono);font-size:11px;color:var(--slate);text-align:right;margin:-6px 0 6px}
.config .btn{width:100%;margin-top:8px}
.note{grid-column:1/-1;display:flex;gap:12px;align-items:flex-start;background:#fffbe9;border:1px solid #f6e6a8;border-radius:12px;padding:14px 16px}
.note .ni{width:24px;height:24px;border-radius:50%;background:#f0d979;color:#7a5c00;display:grid;place-items:center;flex-shrink:0}.note .ni svg{width:14px;height:14px}
.note p{font-size:12.5px;color:#6b5a1f;line-height:1.55}.note a{color:var(--blue);font-weight:600}
.modal-foot{padding:14px 26px;border-top:1px solid var(--line);text-align:right;background:var(--ice)}.modal-foot a{font-family:var(--mono);font-size:13px;font-weight:600;color:var(--orange-d)}.modal-foot a:hover{color:var(--orange)}
.cart-overlay{position:fixed;inset:0;z-index:205;background:rgba(4,18,42,.5);backdrop-filter:blur(3px);opacity:0;visibility:hidden;transition:opacity .34s var(--ease),visibility .34s}
.cart-overlay.open{opacity:1;visibility:visible}
.cart{position:fixed;top:0;right:0;bottom:0;z-index:210;width:min(430px,94vw);background:var(--ice);box-shadow:-30px 0 80px -30px rgba(4,18,42,.55);transform:translateX(100%);transition:transform .38s var(--ease);display:flex;flex-direction:column}
.cart.open{transform:none}
.cart-h{position:relative;display:flex;align-items:center;justify-content:space-between;padding:22px 22px;background:linear-gradient(135deg,var(--navy),var(--navy-2));color:#fff;overflow:hidden}
.cart-h::after{content:"";position:absolute;right:-40px;top:-40px;width:150px;height:150px;background:radial-gradient(circle,rgba(255,140,26,.35),transparent 70%);pointer-events:none}
.cart-h b{font-family:var(--disp);font-size:19px;color:#fff;display:flex;align-items:center;gap:11px;font-weight:800}
.cart-h .ch-ic{width:34px;height:34px;border-radius:10px;background:linear-gradient(135deg,var(--orange),var(--orange-d));display:grid;place-items:center;box-shadow:0 6px 16px -6px rgba(255,140,26,.9)}.cart-h .ch-ic svg{width:18px;height:18px;color:#fff}
.cart-h .ch-count{font-family:var(--mono);font-size:11px;font-weight:500;color:#bcd2f5;letter-spacing:.04em}
.cart-x{width:34px;height:34px;border-radius:9px;border:0;background:rgba(255,255,255,.12);color:#fff;cursor:pointer;display:grid;place-items:center;transition:.2s}.cart-x:hover{background:rgba(255,255,255,.24);transform:rotate(90deg)}.cart-x svg{width:16px;height:16px}
.cart-items{flex:1;overflow-y:auto;padding:18px 20px;display:flex;flex-direction:column;gap:13px}
.cart-empty{text-align:center;color:var(--slate);padding:64px 20px;font-size:14px}.cart-empty svg{width:52px;height:52px;color:#c3d1e8;margin:0 auto 14px}
.citem{position:relative;background:#fff;border:1px solid var(--line);border-radius:15px;padding:15px 16px 15px 20px;box-shadow:0 6px 18px -14px rgba(4,18,42,.35);animation:cin .32s var(--ease);overflow:hidden}
.citem::before{content:"";position:absolute;left:0;top:0;bottom:0;width:5px;background:var(--pc,var(--blue))}
@keyframes cin{from{opacity:0;transform:translateX(16px)}}
.ci-top{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}
.ci-name b{font-family:var(--disp);font-size:15px;color:var(--navy);display:block;line-height:1.2}
.ci-name .ci-sub{font-family:var(--mono);font-size:10.5px;color:var(--slate);text-transform:uppercase;letter-spacing:.06em;margin-top:3px;display:inline-block}
.ci-rm{width:26px;height:26px;border-radius:8px;border:0;background:var(--ice);color:var(--slate);cursor:pointer;display:grid;place-items:center;transition:.2s;flex-shrink:0}.ci-rm:hover{background:#ffe1e1;color:#e03131}.ci-rm svg{width:13px;height:13px}
.ci-bot{display:flex;justify-content:space-between;align-items:center;margin-top:13px}
.qstep{display:flex;align-items:center;gap:2px;border:1px solid var(--line);border-radius:9px;overflow:hidden;background:var(--ice)}
.qstep button{width:30px;height:30px;border:0;background:transparent;color:var(--navy);font-size:17px;font-weight:700;cursor:pointer;display:grid;place-items:center;transition:.15s}.qstep button:hover{background:var(--blue-soft);color:var(--blue)}
.qstep span{min-width:30px;text-align:center;font-family:var(--disp);font-weight:700;font-size:14px;color:var(--navy)}
.ci-price{font-family:var(--disp);font-size:17px;font-weight:800;color:var(--navy)}
.cart-foot{border-top:1px solid var(--line);padding:18px 22px;background:#fff}
.cart-row{display:flex;justify-content:space-between;align-items:center;font-size:14px;color:var(--slate);margin-bottom:8px}.cart-row b{font-family:var(--disp);font-size:15px;color:var(--ink);font-weight:700}
.cart-row.muted b{font-weight:600;color:var(--slate)}
.cart-total{display:flex;justify-content:space-between;align-items:baseline;padding-top:12px;margin:6px 0 16px;border-top:1px dashed var(--line)}.cart-total span{font-family:var(--disp);font-size:16px;font-weight:700;color:var(--navy)}.cart-total b{font-family:var(--disp);font-size:26px;font-weight:800;color:var(--navy)}
.cart-checkout{width:100%;margin-bottom:9px}
.cart-continue{width:100%;background:transparent;border:1.5px solid var(--line);border-radius:12px;padding:11px;font-family:var(--body);font-weight:600;font-size:14px;color:var(--slate);cursor:pointer;transition:.2s}.cart-continue:hover{border-color:var(--blue);color:var(--blue);background:var(--blue-soft)}
.cart-trust{text-align:center;font-family:var(--mono);font-size:10.5px;color:var(--slate);margin-top:13px;letter-spacing:.02em}
.toast{position:fixed;bottom:24px;left:50%;transform:translate(-50%,120%);z-index:230;background:var(--navy);color:#fff;padding:13px 20px;border-radius:12px;font-size:14px;display:flex;align-items:center;gap:10px;box-shadow:var(--shadow-lg);transition:transform .35s var(--ease)}.toast.show{transform:translate(-50%,0)}.toast .tk{width:22px;height:22px;border-radius:50%;background:var(--ok);display:grid;place-items:center;flex-shrink:0}.toast .tk svg{width:13px;height:13px}

.rv{opacity:0;transform:translateY(24px);transition:opacity .7s var(--ease),transform .7s var(--ease)}
.rv.in{opacity:1;transform:none}
.rv[data-d="1"]{transition-delay:.06s}.rv[data-d="2"]{transition-delay:.12s}.rv[data-d="3"]{transition-delay:.18s}.rv[data-d="4"]{transition-delay:.24s}
.tilt{transition:transform .2s var(--ease)}

@media (max-width:1024px){
  .hero-inner{grid-template-columns:1fr;gap:56px}.ssl-stage{max-width:460px;margin:0 auto}.orbit-ring{display:none}
  .pp-vgrid,.pgrid,.pp-feats,.pp-why{grid-template-columns:1fr 1fr}
  .pp-addons,.pp-bens,.pp-uses{grid-template-columns:1fr 1fr}
  .pp-auto{grid-template-columns:1fr}.pp-auto ul{grid-template-columns:1fr 1fr}
}
@media (max-width:860px){
  .modal-body{grid-template-columns:1fr}.pp-secrows{grid-template-columns:1fr}
}
@media (max-width:640px){
  .pp-vgrid,.pgrid,.pp-feats,.pp-why,.pp-addons,.pp-bens,.pp-uses{grid-template-columns:1fr}.pp-auto ul{grid-template-columns:1fr}
}
@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}.rv{opacity:1;transform:none}}
/* ===== remote access ===== */
.portal-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;padding:16px}
.papp{background:#fff;border:1px solid var(--line);border-radius:12px;padding:12px 8px;display:flex;flex-direction:column;align-items:center;gap:7px;transition:.2s var(--ease)}
.papp:hover{border-color:#c9dcfb;transform:translateY(-2px);box-shadow:0 12px 24px -16px rgba(4,18,42,.4)}
.papp .pai{width:38px;height:38px;border-radius:11px;display:grid;place-items:center;color:#fff;font-family:var(--disp);font-weight:800;font-size:15px;background:var(--ac,#1565D8)}
.papp b{font-family:var(--disp);font-size:10.5px;color:var(--navy);text-align:center;line-height:1.1}
.ts-badge{display:inline-flex;align-items:center;gap:8px}
.ts-badge .ts-mark{width:28px;height:28px;border-radius:9px;background:linear-gradient(135deg,#22b8cf,#0b7285);display:grid;place-items:center;flex-shrink:0}
.ts-badge .ts-mark svg{width:17px;height:17px;color:#fff}
.ts-badge .ts-word{font-family:var(--disp);font-weight:800;font-size:19px;color:var(--navy);letter-spacing:-.01em}
.ts-badge .ts-word span{color:#0b7285}
/* ===== architecture diagram (hero) ===== */
.arch{position:relative;z-index:2;background:linear-gradient(180deg,#0A2A57,#04162E);border:1px solid rgba(255,255,255,.12);border-radius:18px;padding:14px;box-shadow:var(--shadow-lg);width:100%}
.arch-tier{border:1.5px solid var(--orange);border-radius:12px;padding:11px 12px;background:rgba(255,255,255,.03)}
.arch-lbl{display:flex;align-items:center;gap:7px;color:#fff;font-family:var(--disp);font-weight:700;font-size:12px;margin-bottom:9px}
.arch-lbl svg{width:15px;height:15px;color:var(--orange)}
.arch-devices{display:flex;justify-content:center;align-items:flex-end;gap:20px;padding:4px 0 6px;color:#c9d8f2}
.arch-devices svg{color:#c9d8f2}
.arch-flow{text-align:center;color:#dfe8f6;font-family:var(--mono);font-size:9px;letter-spacing:.05em;text-transform:uppercase;padding:8px 0 6px;line-height:1.3}
.arch-flow:before{content:"";display:block;width:0;height:0;border-left:8px solid transparent;border-right:8px solid transparent;border-top:8px solid var(--orange);margin:0 auto 5px}
.arch-brandbar{display:flex;align-items:center;justify-content:center;gap:8px;font-family:var(--disp);font-weight:800;font-size:20px;letter-spacing:.01em;color:#fff;padding:6px 0}
.arch-brandbar .tsq{display:flex;flex-direction:column;line-height:.82;font-size:13px;color:var(--orange);font-weight:800;text-align:center;border-right:2px solid rgba(255,255,255,.4);padding-right:8px}
.arch-brandbar .tsq small{font-size:6.5px;letter-spacing:.16em;color:#c9d8f2}
.arch-brandbar b{color:var(--orange)}
.arch-cols{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}
.arch-col{background:#fff;border-radius:9px;padding:10px 8px;text-align:center}
.arch-col .ct{font-family:var(--body);font-size:7.5px;font-weight:700;color:var(--slate);margin-bottom:8px}
.arch-apps{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;place-items:center}
.arch-apps .ap{width:19px;height:19px;border-radius:5px;display:grid;place-items:center;color:#fff;font-family:var(--disp);font-weight:800;font-size:8px}
.arch-yourapp{background:var(--orange);color:#fff;font-family:var(--disp);font-weight:700;font-size:8px;border-radius:6px;padding:12px 6px;line-height:1.3}
.arch-net{display:flex;justify-content:center;gap:14px;color:var(--slate)}
.arch-net div{display:flex;flex-direction:column;align-items:center;gap:3px;font-family:var(--body);font-size:6.5px;font-weight:700;color:var(--slate)}
.arch-net svg{width:22px;height:20px;color:var(--navy)}
@media(max-width:520px){.arch-cols{grid-template-columns:1fr}}
/* ===== more amazing features (tabs) ===== */
.ft-head{text-align:center;margin-bottom:22px}
.ft-sub{font-family:var(--mono);font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:var(--orange-d);font-weight:700}
.ft-tabs{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin-bottom:-1px}
.ft-tab{font-family:var(--disp);font-weight:600;font-size:14px;color:var(--slate);background:#eef2f9;border:1px solid var(--line);border-radius:12px 12px 0 0;padding:12px 20px;cursor:pointer;transition:.18s}
.ft-tab:hover{color:var(--blue)}
.ft-tab.active{background:#fff;color:var(--navy);border-bottom-color:#fff;position:relative;z-index:2}
.ft-panels{background:#fff;border:1px solid var(--line);border-radius:0 16px 16px 16px;box-shadow:0 24px 50px -30px rgba(4,18,42,.4)}
.ft-panel{display:none;grid-template-columns:1fr 1fr;gap:34px;align-items:center;padding:34px}
.ft-panel.active{display:grid}
.ft-panel h3{font-size:22px;color:var(--navy);margin-bottom:12px}
.ft-panel p{font-size:14.5px;color:var(--slate);line-height:1.7;margin-bottom:16px}
.ft-list{list-style:none;display:flex;flex-direction:column;gap:10px}
.ft-list li{display:flex;gap:10px;align-items:flex-start;font-size:14px;color:var(--ink)}
.ft-list li .ck{width:20px;height:20px;border-radius:50%;background:var(--blue-soft);color:var(--blue);display:grid;place-items:center;flex-shrink:0;margin-top:1px}.ft-list li .ck svg{width:12px;height:12px}
.ft-shot{background:linear-gradient(135deg,#101826,#1c2942);border:1px solid var(--line);border-radius:14px;padding:14px;box-shadow:0 16px 34px -22px rgba(4,18,42,.5)}
.ft-win{background:#0f1a2e;border-radius:10px;overflow:hidden;box-shadow:0 10px 26px -14px rgba(0,0,0,.6);border:1px solid rgba(255,255,255,.08)}
.ft-win .wb{display:flex;align-items:center;gap:6px;background:linear-gradient(90deg,#0f1a2e,#1c2942);padding:8px 10px;border-bottom:1px solid rgba(255,255,255,.06)}
.ft-win .wb .tsm{font-family:var(--disp);font-weight:800;font-size:8px;color:var(--orange);line-height:.8;text-align:center}.ft-win .wb .tsm small{font-size:5px;letter-spacing:.14em;color:#8ea4c6;display:block}
.ft-win .wb b{margin-left:auto;font-family:var(--mono);font-size:8px;color:#8ea4c6;font-weight:600}
.ft-win .wbody{padding:16px;min-height:150px;display:flex;flex-direction:column;justify-content:center;gap:11px;background:radial-gradient(circle at 78% 30%,#20345c,#0f1a2e 70%)}
.ft-win .wfield{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);border-radius:8px;padding:9px 11px;display:flex;align-items:center;gap:9px;color:#c9d8f2;font-size:9px}
.ft-win .wfield .ic{width:18px;height:18px;color:var(--orange);flex-shrink:0}.ft-win .wfield .ic svg{width:18px;height:18px}
.ft-win .wfield .fl{flex:1;min-width:0}.ft-win .wfield .fl b{display:block;font-family:var(--disp);font-size:10px;color:#fff}.ft-win .wfield .fl span{font-size:8px;color:#8ea4c6}
.ft-win .wgo{font-family:var(--disp);font-weight:700;font-size:9px;color:#fff;background:var(--orange);border-radius:6px;padding:8px 0;text-align:center}
.ft-shotcap{font-family:var(--mono);font-size:10px;color:#8ea4c6;text-align:center;margin-top:10px}
@media(max-width:820px){.ft-panel{grid-template-columns:1fr;gap:22px;padding:24px}.ft-panels{border-radius:16px}}
/* Microsoft badge */
.ms-badge{display:inline-flex;align-items:center;gap:8px}
.ms-badge .ms-sq{display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;gap:2px;width:22px;height:22px;flex-shrink:0}
.ms-badge .ms-sq i{display:block;border-radius:1px}
.ms-badge .ms-sq i:nth-child(1){background:#F25022}.ms-badge .ms-sq i:nth-child(2){background:#7FBA00}.ms-badge .ms-sq i:nth-child(3){background:#00A4EF}.ms-badge .ms-sq i:nth-child(4){background:#FFB900}
.ms-badge .ms-word{font-family:var(--disp);font-weight:700;font-size:16px;color:var(--navy)}
.papp .pai.cop{background:conic-gradient(from 180deg,#0b6dff,#33c1ff,#7c4dff,#0b6dff)}
/* Azure badge */
.aws-badge{display:inline-flex;align-items:center;gap:7px}
.aws-badge .aw-mark{width:22px;height:22px;flex-shrink:0;color:#0089D6}
.aws-badge .aw-mark svg{width:22px;height:22px}
.aws-badge .aw{font-family:var(--disp);font-weight:700;font-size:18px;color:var(--navy);letter-spacing:.01em}
.aws-badge .sm{display:none}
/* ===== before / after ===== */
.ba-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;align-items:stretch;position:relative}
.ba-col{border-radius:18px;padding:26px 24px}
.ba-col.before{background:linear-gradient(180deg,#0A2A57,#04162E);color:#fff}
.ba-col.after{background:#fff;border:1px solid var(--line);box-shadow:var(--shadow-s)}
.ba-head{display:flex;align-items:center;gap:12px;margin-bottom:20px}
.ba-head .bi{width:40px;height:40px;border-radius:50%;display:grid;place-items:center;flex-shrink:0}
.ba-col.before .bi{background:rgba(229,72,77,.18);color:#ff6b6f}
.ba-col.after .bi{background:#e4f7ec;color:#16a34a}
.ba-head .bt{font-family:var(--mono);font-size:12px;font-weight:700;letter-spacing:.1em;text-transform:uppercase}
.ba-col.before .bt{color:#ff6b6f}.ba-col.after .bt{color:var(--blue)}
.ba-head .bs{font-size:12.5px;margin-top:2px}
.ba-col.before .bs{color:#9fb4d6}.ba-col.after .bs{color:var(--slate)}
.ba-items{display:grid;grid-template-columns:1fr 1fr;gap:20px 18px}
.ba-item{display:flex;flex-direction:column;gap:6px}
.ba-item .ii{width:34px;height:34px;border-radius:10px;display:grid;place-items:center;position:relative}
.ba-col.before .ii{background:rgba(255,255,255,.06);color:#9fb4d6}
.ba-col.after .ii{background:var(--blue-soft);color:var(--blue)}
.ba-item .ii svg{width:17px;height:17px}
.ba-item .ii .ok{position:absolute;top:-4px;right:-4px;width:15px;height:15px;border-radius:50%;background:#16a34a;color:#fff;display:grid;place-items:center;border:2px solid #fff}
.ba-item .ii .ok svg{width:8px;height:8px}
.ba-item b{font-family:var(--disp);font-size:14px;line-height:1.2}
.ba-col.before .ba-item b{color:#fff}.ba-col.after .ba-item b{color:var(--navy)}
.ba-item p{font-size:11.5px;line-height:1.5;margin:0}
.ba-col.before .ba-item p{color:#8ea4c6}.ba-col.after .ba-item p{color:var(--slate)}
.ba-arrow{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:46px;height:46px;border-radius:50%;background:var(--blue);color:#fff;display:grid;place-items:center;box-shadow:0 12px 26px -10px rgba(21,101,216,.7);z-index:3}
.ba-arrow svg{width:20px;height:20px}
@media(max-width:860px){.ba-grid{grid-template-columns:1fr}.ba-arrow{display:none}.ba-items{grid-template-columns:1fr}}
/* ===== scenario cards ===== */
.scn-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.scn{border:1px solid var(--line);border-radius:16px;background:#fff;padding:24px;box-shadow:var(--shadow-s);transition:.25s var(--ease)}
.scn:hover{transform:translateY(-4px);box-shadow:0 26px 54px -30px rgba(4,18,42,.45)}
.scn-h{display:flex;align-items:center;gap:12px;margin-bottom:12px}
.scn-h .si{width:40px;height:40px;border-radius:11px;background:var(--blue-soft);color:var(--blue);display:grid;place-items:center;flex-shrink:0}.scn-h .si svg{width:20px;height:20px}
.scn-h h3{font-size:16.5px;color:var(--navy);margin:0;line-height:1.2}
.scn>p{font-size:13px;color:var(--slate);line-height:1.6;margin:0 0 14px}
.scn .dst-l{font-family:var(--mono);font-size:9.5px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--blue);margin-bottom:4px}
.scn .dst{font-size:12.5px;font-weight:600;color:var(--ink);margin-bottom:16px}
.scn-proj{background:var(--ice);border-radius:12px;padding:14px;display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:14px}
.scn-proj .pl{font-family:var(--mono);font-size:8.5px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--slate)}
.scn-proj .pn{font-family:var(--disp);font-weight:800;font-size:14px;color:var(--navy);margin:3px 0 4px;line-height:1.15}
.scn-proj .pd{font-size:10.5px;color:var(--slate);line-height:1.4}
.scn-proj .pm{text-align:right;flex-shrink:0}
.scn-proj .pm b{font-family:var(--disp);font-weight:800;font-size:22px;color:var(--blue);display:block;line-height:1}
.scn-proj .pm span{font-size:9px;color:var(--slate)}
.scn-tags{display:flex;flex-wrap:wrap;gap:7px}
.scn-tags span{font-family:var(--body);font-weight:600;font-size:11px;border-radius:99px;padding:5px 11px;display:inline-flex;align-items:center;gap:5px;border:1px solid}
.scn-tags .g{background:#e8f9ef;border-color:#bfead0;color:#15803d}
.scn-tags .p{background:#f2ecfe;border-color:#ddd0fa;color:#6d28d9}
.scn-tags .b{background:var(--blue-soft);border-color:#c9dcfb;color:#0C3E8F}
@media(max-width:980px){.scn-grid{grid-template-columns:1fr}}
/* ===== migration process timeline ===== */
.mp-rail{display:none}
.mp-phases{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:8px}
.mp-phase{border:1px solid var(--line);border-radius:16px;overflow:hidden;background:#fff}
.mp-ph-head{padding:18px 18px 14px;text-align:center;background:linear-gradient(180deg,#f4f7fc,#fff)}
.mp-badge{display:inline-flex;align-items:center;gap:7px;font-family:var(--disp);font-weight:800;font-size:12px;letter-spacing:.08em;color:#fff;border-radius:99px;padding:5px 14px 5px 6px;margin-bottom:10px}
.mp-badge .n{width:20px;height:20px;border-radius:50%;background:rgba(255,255,255,.25);display:grid;place-items:center;font-size:10px}
.mp-ph-head p{font-size:12px;color:var(--slate);line-height:1.5;margin:0}
.mp-steps{display:grid;grid-template-columns:1fr 1fr;gap:0}
.mp-step{padding:16px 14px;border-top:1px solid var(--line)}
.mp-step:nth-child(odd){border-right:1px solid var(--line)}
.mp-step .sn{font-family:var(--disp);font-weight:800;font-size:15px;color:var(--blue);text-align:center}
.mp-step .sic{width:44px;height:44px;border-radius:50%;border:1.5px solid var(--line);display:grid;place-items:center;margin:8px auto;color:var(--navy)}.mp-step .sic svg{width:20px;height:20px}
.mp-step .st{font-family:var(--disp);font-weight:700;font-size:13px;color:var(--navy);text-align:center;margin-bottom:4px}
.mp-step .sd{font-size:10.5px;color:var(--slate);text-align:center;line-height:1.4;margin-bottom:9px;min-height:42px}
.mp-step ul{list-style:none;display:flex;flex-direction:column;gap:4px}
.mp-step li{font-size:10.5px;color:var(--ink);display:flex;align-items:center;gap:6px}
.mp-step li:before{content:"";width:5px;height:5px;border-radius:50%;background:var(--blue);flex-shrink:0}
@media(max-width:980px){.mp-phases{grid-template-columns:1fr 1fr}}
@media(max-width:560px){.mp-phases{grid-template-columns:1fr}}
/* ===== why row ===== */
.why-row{display:grid;grid-template-columns:repeat(5,1fr);gap:0;border:1px solid var(--line);border-radius:16px;overflow:hidden;background:#fff;box-shadow:var(--shadow-s)}
.why-cell{padding:24px 20px;border-right:1px solid var(--line)}
.why-cell:last-child{border-right:none}
.why-cell .wi{width:38px;height:38px;border-radius:10px;background:var(--blue-soft);color:var(--blue);display:grid;place-items:center;margin-bottom:12px}.why-cell .wi svg{width:19px;height:19px}
.why-cell b{font-family:var(--disp);font-size:14.5px;color:var(--navy);display:block;margin-bottom:6px}
.why-cell p{font-size:12px;color:var(--slate);line-height:1.55;margin:0}
@media(max-width:980px){.why-row{grid-template-columns:1fr 1fr 1fr}.why-cell:nth-child(3){border-right:none}}
@media(max-width:560px){.why-row{grid-template-columns:1fr}.why-cell{border-right:none;border-bottom:1px solid var(--line)}}
/* ===== journey timeline ===== */
.jn-wrap{position:relative;padding:20px 0}
.jn-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:12px}
.jn-step{text-align:center;position:relative}
.jn-ring{width:74px;height:74px;border-radius:50%;margin:0 auto 14px;display:grid;place-items:center;position:relative;background:#fff;border:3px solid var(--line)}
.jn-ring svg{width:30px;height:30px}
.jn-step.c1 .jn-ring{border-color:#7ab648;color:#7ab648}
.jn-step.c2 .jn-ring{border-color:#1aa37a;color:#1aa37a}
.jn-step.c3 .jn-ring{border-color:#17b0c4;color:#17b0c4}
.jn-step.c4 .jn-ring{border-color:#1565D8;color:#1565D8}
.jn-step.c5 .jn-ring{border-color:#7c4dff;color:#7c4dff}
.jn-step.c6 .jn-ring{border-color:#9b4dff;color:#9b4dff}
.jn-num{font-family:var(--disp);font-weight:800;font-size:15px;margin-bottom:3px}
.jn-step.c1 .jn-num{color:#7ab648}.jn-step.c2 .jn-num{color:#1aa37a}.jn-step.c3 .jn-num{color:#17b0c4}
.jn-step.c4 .jn-num{color:#1565D8}.jn-step.c5 .jn-num{color:#7c4dff}.jn-step.c6 .jn-num{color:#9b4dff}
.jn-step h4{font-family:var(--disp);font-weight:800;font-size:15px;color:var(--navy);margin:0 0 5px}
.jn-step p{font-size:11.5px;color:var(--slate);line-height:1.45;margin:0}
@media(max-width:900px){.jn-grid{grid-template-columns:1fr 1fr 1fr}}
@media(max-width:520px){.jn-grid{grid-template-columns:1fr 1fr}}
/* ===== ecosystem partner cards ===== */
.eco-grid{display:grid;gap:18px}
.eco-grid.g3{grid-template-columns:1fr 1fr 1.4fr}
.eco-grid.g4{grid-template-columns:repeat(4,1fr)}
.eco-card{border:1px solid var(--line);border-radius:16px;background:#fff;padding:22px;box-shadow:var(--shadow-s)}
.eco-h{display:flex;align-items:flex-start;gap:12px;margin-bottom:16px}
.eco-h .ei{width:38px;height:38px;border-radius:10px;background:var(--blue-soft);color:var(--blue);display:grid;place-items:center;flex-shrink:0}.eco-h .ei svg{width:20px;height:20px}
.eco-h b{font-family:var(--mono);font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--navy);display:block;margin-bottom:3px}
.eco-h span{font-size:12px;color:var(--slate);line-height:1.45}
.eco-logos{display:flex;flex-wrap:wrap;gap:9px}
.eco-logos .lg{display:inline-flex;align-items:center;gap:7px;border:1px solid var(--line);border-radius:9px;padding:8px 13px;background:#fbfcfe;font-family:var(--disp);font-weight:700;font-size:13px;color:var(--navy)}
.eco-logos .lg i{width:9px;height:9px;border-radius:2px;display:block;flex-shrink:0}
.eco-strip{display:grid;grid-template-columns:repeat(4,1fr);gap:0;border:1px solid var(--line);border-radius:12px;overflow:hidden;background:#f4f8ff;margin-top:16px}
.eco-strip .es{padding:14px 18px;display:flex;align-items:center;gap:9px;font-family:var(--disp);font-weight:700;font-size:12.5px;color:var(--navy);border-right:1px solid var(--line)}
.eco-strip .es:last-child{border-right:none}
.eco-strip .es svg{width:16px;height:16px;color:var(--blue);flex-shrink:0}
@media(max-width:900px){.eco-grid.g3,.eco-grid.g4{grid-template-columns:1fr 1fr}.eco-strip{grid-template-columns:1fr 1fr}.eco-strip .es:nth-child(2){border-right:none}}
@media(max-width:560px){.eco-grid.g3,.eco-grid.g4{grid-template-columns:1fr}}
/* ===== layered architecture ===== */
.arch-layer{display:grid;grid-template-columns:170px 1fr;gap:20px;align-items:start;margin-bottom:22px}
.arch-side .num{width:30px;height:30px;border-radius:50%;background:var(--blue);color:#fff;display:grid;place-items:center;font-family:var(--disp);font-weight:800;font-size:14px;margin-bottom:10px}
.arch-side h4{font-family:var(--mono);font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--navy);margin:0 0 6px;line-height:1.3}
.arch-side p{font-size:12px;color:var(--slate);line-height:1.5;margin:0}
.arch-body{border:1px solid var(--line);border-radius:16px;background:var(--ice);padding:18px}
.arch-obj{display:flex;justify-content:center;margin-bottom:12px}
.arch-obj .pill{display:inline-flex;align-items:center;gap:10px;background:#fff;border:1px solid var(--line);border-radius:99px;padding:10px 22px;box-shadow:var(--shadow-s)}
.arch-obj .pill b{font-family:var(--disp);font-weight:800;font-size:14px;color:var(--blue)}
.arch-obj .pill span{font-size:12px;color:var(--slate)}
.arch-cards{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}
.arch-c{background:#fff;border:1px solid var(--line);border-radius:12px;padding:16px 12px;text-align:center}
.arch-c .ac-i{color:var(--blue);margin-bottom:8px}.arch-c .ac-i svg{width:22px;height:22px}
.arch-c b{font-family:var(--disp);font-weight:800;font-size:13.5px;color:var(--navy);display:block;margin-bottom:5px}
.arch-c p{font-size:10.5px;color:var(--slate);line-height:1.4;margin:0}
.arch-plane{background:linear-gradient(135deg,#1565D8,#0C3E8F);border-radius:14px;padding:16px;text-align:center;color:#fff;margin-top:12px}
.arch-plane b{font-family:var(--disp);font-weight:800;font-size:15px;display:block;margin-bottom:3px}
.arch-plane span{font-size:12px;color:#cfe0fb}
.arch-tabs{display:flex;flex-direction:column;gap:6px;background:#fff;border:1px solid var(--blue-soft);border-radius:12px;padding:12px}
.arch-tabs .at-h{display:flex;align-items:center;gap:7px;font-family:var(--disp);font-weight:800;font-size:13px;color:var(--blue);margin-bottom:4px}
.arch-tabs .at{font-family:var(--body);font-weight:600;font-size:12px;color:var(--navy);border:1px solid var(--line);border-radius:7px;padding:7px 11px;text-align:center}
.arch-row{display:grid;grid-template-columns:repeat(6,1fr);gap:10px}
.arch-row.n9{grid-template-columns:repeat(9,1fr)}
.arch-mini{background:#fff;border:1px solid var(--line);border-radius:11px;padding:14px 8px;text-align:center}
.arch-mini .ac-i{color:var(--blue);margin-bottom:7px}.arch-mini .ac-i svg{width:20px;height:20px}
.arch-mini b{font-family:var(--disp);font-weight:700;font-size:11.5px;color:var(--navy);line-height:1.25}
.arch-flow .arch-body{background:#fff}
.arch-flow .arch-row{align-items:start}
.arch-dark .arch-body{background:linear-gradient(160deg,#0f1e33,#0a1526);border-color:#1b3057}
.arch-dark .arch-mini{background:rgba(255,255,255,.04);border-color:#1e3a5f}
.arch-dark .arch-mini .ac-i{color:#5b9dff}
.arch-dark .arch-mini b{color:#fff}
.arch-dark .arch-mini span{display:block;font-size:9px;color:#8fa6c8;margin-top:4px;line-height:1.4}
@media(max-width:900px){.arch-layer{grid-template-columns:1fr}.arch-cards{grid-template-columns:1fr 1fr 1fr}.arch-row,.arch-row.n9{grid-template-columns:1fr 1fr 1fr}}
@media(max-width:560px){.arch-cards,.arch-row,.arch-row.n9{grid-template-columns:1fr 1fr}}
`;
