// src/app/data/watchtower-reference.data.ts
var WATCHTOWER_REFERENCE_STYLES = `
:host{--navy:#041E42;--navy2:#062A5C;--blue:#1565D8;--blue2:#3B82F6;--sky:#8AB4FF;--soft:#E8F0FD;--ice:#F2F6FC;--orange:#FF8C1A;--orange2:#FFB15C;--green:#16A34A;--ink:#0B1730;--mute:#5B6B85;--line:#DCE5F3;--font-h:'Sora',sans-serif;--font-b:'IBM Plex Sans',sans-serif;--font-m:'IBM Plex Mono',monospace;--font-s:'Instrument Serif',serif;--font-d:'Fraunces',Georgia,serif;--royal:#1F5BD9;--royal2:#163F9E;--royal3:#0E2A66;--r:16px;--sh:0 10px 30px rgba(4,30,66,.08);--sh2:0 22px 60px rgba(4,30,66,.16)}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth;scroll-padding-top:90px}
body{font-family:var(--font-b);color:var(--ink);background:#fff;line-height:1.6;overflow-x:hidden;-webkit-font-smoothing:antialiased}
img,svg{display:block;max-width:100%}
a{color:inherit;text-decoration:none}
button{font-family:inherit;cursor:pointer;border:0;background:none;color:inherit}
ul{list-style:none}
.wrap{width:min(1200px,92vw);margin:0 auto}
h1,h2,h3,h4{font-family:var(--font-h);line-height:1.15;letter-spacing:-.01em;color:var(--navy)}
:focus-visible{outline:3px solid var(--orange);outline-offset:2px}
/* top bars */
.wide{width:min(1520px,94vw);margin:0 auto}
.utility{background:#0B1F4A;color:#DCE7FF;font:500 13.5px/1 var(--font-b)}
.utility .wide{display:flex;justify-content:space-between;align-items:center;gap:16px;min-height:52px}
.utility .u-l{display:flex;gap:18px;align-items:center;white-space:nowrap}
.utility .u-l a:hover{color:#fff;text-decoration:underline}
.utility .u-r{display:flex;gap:14px;align-items:center;white-space:nowrap}
.utility .u-r b{font-weight:700;color:#fff}
.utility .moon{width:38px;height:38px;border-radius:50%;background:rgba(255,255,255,.12);display:grid;place-items:center;color:#fff}
.utility .moon svg,.utility .wa svg,.utility .lang svg{width:16px;height:16px}
.utility .lang{border:1px solid rgba(255,255,255,.35);border-radius:999px;padding:8px 16px;font:700 13px var(--font-m);color:#fff;display:inline-flex;gap:8px;align-items:center}
.utility .wa{color:#4ADE80;font-weight:700;display:inline-flex;gap:6px;align-items:center}
.promo{background:linear-gradient(90deg,#1A4CBC 0%,#1F5FD9 40%,#1F5FD9 60%,#1A4CBC 100%);color:#fff;text-align:center;font:700 15.5px/1.4 var(--font-b);padding:11px 12px;display:flex;justify-content:center;gap:12px;align-items:center;flex-wrap:wrap}
.promo .code{background:#4A7EE3;font:700 13px var(--font-m);padding:6px 13px;border-radius:6px;letter-spacing:.08em;color:#fff}
.promo .dot{opacity:.7}
.promo a{text-decoration:underline;font-weight:700}
/* header */
.site-head{position:sticky;top:0;z-index:100;background:#fff;border-bottom:1px solid var(--line);transition:box-shadow .3s}
.site-head.scrolled{box-shadow:0 8px 30px rgba(4,30,66,.12)}
.site-head .wide{display:flex;align-items:center;justify-content:space-between;height:106px;gap:16px;position:relative}
.logo{display:block;flex:none}
.logo .lg-mark{display:block;width:194px;height:96px;background:url(data:image/png;base64,) no-repeat center/contain}
.site-foot .logo .lg-mark{width:150px;height:74px}
.nav{display:flex;gap:0;align-items:center}
.nav>li{position:relative}
.nav>li>a{display:flex;align-items:center;gap:6px;padding:10px 12px;font:700 15px var(--font-b);color:#0B1F4A;border-radius:8px;transition:.2s;white-space:nowrap}
.nav>li>a svg{width:11px;height:11px;opacity:.55}
.nav>li>a:hover,.nav>li.on>a{background:var(--soft);color:var(--blue)}
.mm{position:absolute;top:100%;left:50%;transform:translate(-50%,10px);background:#fff;border:1px solid var(--line);border-radius:18px;box-shadow:var(--sh2);padding:24px;width:900px;display:grid;grid-template-columns:repeat(4,1fr);gap:20px;opacity:0;visibility:hidden;transition:.25s;margin-top:6px}
.mm::before{content:"";position:absolute;left:0;right:0;top:-12px;height:12px}
.has-mm:hover .mm,.has-mm.open .mm{opacity:1;visibility:visible;transform:translate(-50%,0)}
.mm h5{font:700 11px var(--font-m);letter-spacing:.12em;text-transform:uppercase;color:var(--orange);margin-bottom:10px;padding-bottom:8px;border-bottom:1px solid var(--line)}
.mm a{display:block;padding:8px 9px;border-radius:9px;font-size:13.5px;color:var(--navy);font-weight:600;transition:.2s}
.mm a small{display:block;font-weight:400;color:var(--mute);font-size:12px;line-height:1.35;margin-top:2px}
.mm a:hover{background:var(--soft);color:var(--blue)}
.mm .all{grid-column:1/-1;border-top:1px solid var(--line);padding-top:12px;display:flex;justify-content:space-between;align-items:center;font-size:13px;color:var(--mute)}
.mm .all a{display:inline-flex;gap:6px;align-items:center;color:var(--blue);padding:6px 10px;white-space:nowrap;font-weight:700}.mm .all a svg{width:14px;height:14px}
.h-act{display:flex;gap:10px;align-items:center;flex:none}
.hicon{width:48px;height:48px;border-radius:12px;border:1px solid var(--line);display:grid;place-items:center;color:#0B1F4A;background:#fff;transition:.2s;position:relative}
.hicon:hover{border-color:var(--blue);color:var(--blue)}
.hicon svg{width:20px;height:20px}
.hicon.docs{background:var(--royal);color:#fff;border-color:var(--royal)}
.cart-btn .cnt{position:absolute;top:-6px;right:-6px;background:var(--orange);color:#fff;font:700 10px var(--font-m);min-width:18px;height:18px;border-radius:9px;display:grid;place-items:center;padding:0 5px}
.btn-login{border:1px solid var(--line);color:#0B1F4A;font:700 15px var(--font-b);padding:13px 22px;border-radius:12px;background:#fff}
.btn-login:hover{border-color:var(--blue);color:var(--blue)}
.btn-signup{background:var(--royal);color:#fff;font:700 15px var(--font-b);padding:14px 22px;border-radius:12px;box-shadow:0 8px 20px rgba(31,91,217,.35)}
.btn-signup:hover{background:#1749B8}
.burger{display:none;width:48px;height:48px;border-radius:12px;border:1px solid var(--line);place-items:center;color:var(--navy)}
.burger svg{width:22px;height:22px}
/* buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:14px 26px;border-radius:12px;font:700 15px var(--font-b);position:relative;overflow:hidden;transition:transform .25s,box-shadow .25s,background .25s;white-space:nowrap}
.btn svg{width:16px;height:16px}
.btn-primary{background:linear-gradient(135deg,#FF9A3C,#FF7A00);color:#fff;box-shadow:0 10px 26px rgba(255,140,26,.38)}
.btn-primary:hover{transform:translateY(-2px);box-shadow:0 16px 34px rgba(255,140,26,.5)}
.btn-blue{background:linear-gradient(135deg,#2F7BEF,#1049B3);color:#fff;box-shadow:0 10px 26px rgba(21,101,216,.35)}
.btn-blue:hover{transform:translateY(-2px);box-shadow:0 16px 34px rgba(21,101,216,.45)}
.btn-ghost{border:1.5px solid rgba(255,255,255,.35);color:#fff;background:rgba(255,255,255,.06);backdrop-filter:blur(6px)}
.btn-ghost:hover{background:rgba(255,255,255,.14);transform:translateY(-2px)}
.btn-line{border:1.5px solid var(--blue);color:var(--blue);background:#fff}
.btn-line:hover{background:var(--soft)}
.btn-green{background:linear-gradient(135deg,#22C55E,#15803D);color:#fff;box-shadow:0 10px 24px rgba(34,197,94,.35)}
.btn-green:hover{transform:translateY(-2px)}
.btn-sm{padding:10px 18px;font-size:13px;border-radius:10px}
.btn .sh{position:absolute;inset:0;background:linear-gradient(115deg,transparent 30%,rgba(255,255,255,.35) 50%,transparent 70%);transform:translateX(-120%);transition:transform .7s}
.btn:hover .sh{transform:translateX(120%)}
/* hero */
.pp-hero{position:relative;background:radial-gradient(1200px 640px at 18% 8%,#0A3A80 0%,var(--navy) 52%,#02122B 100%);color:#fff;overflow:hidden;min-height:660px;display:flex;align-items:center;padding:84px 0 96px}
.aur{position:absolute;border-radius:50%;filter:blur(70px);opacity:.55;pointer-events:none;mix-blend-mode:screen}
.aur.a1{width:540px;height:540px;background:#1565D8;top:-170px;left:-130px;animation:aur1 14s ease-in-out infinite}
.aur.a2{width:440px;height:440px;background:#FF8C1A;bottom:-170px;right:4%;opacity:.32;animation:aur2 18s ease-in-out infinite}
.aur.a3{width:380px;height:380px;background:#6D5BFF;top:18%;right:28%;opacity:.22;animation:aur1 22s ease-in-out infinite reverse}
@keyframes aur1{0%,100%{transform:translate(0,0) scale(1)}50%{transform:translate(60px,40px) scale(1.15)}}
@keyframes aur2{0%,100%{transform:translate(0,0) scale(1)}50%{transform:translate(-50px,-60px) scale(1.1)}}
.grid-bg{position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.05) 1px,transparent 1px);background-size:56px 56px;animation:gdrift 30s linear infinite;pointer-events:none;-webkit-mask-image:radial-gradient(ellipse at 60% 40%,#000 25%,transparent 75%);mask-image:radial-gradient(ellipse at 60% 40%,#000 25%,transparent 75%)}
@keyframes gdrift{to{background-position:56px 56px}}
.scan{position:absolute;left:0;right:0;height:2px;background:linear-gradient(90deg,transparent,rgba(138,180,255,.55),transparent);animation:scan 7s linear infinite;pointer-events:none;top:0}
@keyframes scan{0%{top:0;opacity:0}10%{opacity:1}90%{opacity:1}100%{top:100%;opacity:0}}
#pcv{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}
.spot{position:absolute;width:560px;height:560px;border-radius:50%;background:radial-gradient(circle,rgba(21,101,216,.3),transparent 60%);pointer-events:none;transform:translate(-50%,-50%);transition:opacity .4s;opacity:0}
.pp-hero .wrap{position:relative;z-index:2;display:grid;grid-template-columns:1.05fr .95fr;gap:60px;align-items:center}
.crumb{font:500 12px var(--font-m);color:#8AB4FF;letter-spacing:.06em;margin-bottom:18px;display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.crumb span{opacity:.45}
.badges{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:22px}
.badge{font:600 11.5px var(--font-m);padding:6px 11px;border-radius:999px;border:1px solid rgba(255,255,255,.18);background:rgba(255,255,255,.07);color:#DCE7FF;display:inline-flex;gap:6px;align-items:center}
.badge svg{width:12px;height:12px}
.badge.or{border-color:rgba(255,140,26,.55);color:#FFC98A;background:rgba(255,140,26,.14)}
.eyeb{font:600 13px var(--font-m);letter-spacing:.28em;text-transform:uppercase;color:#FF9A3C;margin-bottom:18px}
.pp-hero h1{font-family:var(--font-d);font-weight:800;font-size:clamp(38px,4.5vw,62px);line-height:1.08;letter-spacing:-.01em;color:#fff;margin-bottom:14px}
.pp-hero h1 .h1b{display:block;color:#FF9A3C;font-size:.6em;font-weight:700;margin-top:8px;line-height:1.18}
.pp-hero h1.big{font-size:clamp(46px,6vw,84px);line-height:1.02}
.pp-hero h1.big .h1b{font-size:1em;margin-top:0}
.pp-hero .sub{font-size:19px;color:#DCE7FF;max-width:620px;margin-bottom:20px;font-weight:400;line-height:1.6}
.hnow{margin:0 0 26px;font:700 16px var(--font-b);color:#fff}.hnow i{font-style:normal;color:#8AB4FF;margin:0 6px}.hnow b{color:#FFB15C}
.hstats{display:flex;gap:44px;flex-wrap:wrap;margin-top:36px}
.hstats div b{display:block;font:700 40px/1 var(--font-m);color:#fff;letter-spacing:-.03em}
.hstats div b em{font-style:normal}
.hstats div span{display:block;font:500 14px var(--font-b);color:#DCE7FF;margin-top:6px}
.hstats div::after{content:"";display:block;width:44px;height:3px;background:#FF8C1A;margin-top:12px;border-radius:2px}
.hctas{display:flex;gap:14px;flex-wrap:wrap;align-items:center}
.hmeta{margin-top:28px;display:flex;gap:28px;flex-wrap:wrap;font:500 11.5px var(--font-m);color:#8AB4FF;letter-spacing:.04em}
.hmeta span b{color:#fff;font:700 18px var(--font-h);display:block;letter-spacing:0}
/* hero visual */
.hvis{position:relative;perspective:1400px}
.console{background:linear-gradient(160deg,rgba(255,255,255,.1),rgba(255,255,255,.035));border:1px solid rgba(255,255,255,.16);border-radius:20px;box-shadow:0 40px 90px rgba(0,0,0,.5),inset 0 1px 0 rgba(255,255,255,.2);backdrop-filter:blur(10px);overflow:hidden;transform:rotateY(-7deg) rotateX(3deg);transition:transform .6s;animation:scfloat 7s ease-in-out infinite}
.hvis:hover .console{transform:rotateY(0) rotateX(0)}
@keyframes scfloat{0%,100%{translate:0 0}50%{translate:0 -12px}}
.c-bar{display:flex;align-items:center;gap:7px;padding:12px 16px;border-bottom:1px solid rgba(255,255,255,.1);background:rgba(0,0,0,.22)}
.c-bar i{width:10px;height:10px;border-radius:50%;display:block}
.c-bar .t{margin-left:8px;font:600 11.5px var(--font-m);color:#B9C8E4;letter-spacing:.08em}
.c-bar .live{margin-left:auto;font:600 10px var(--font-m);color:#4ADE80;display:flex;gap:6px;align-items:center;letter-spacing:.08em}
.c-bar .live::before{content:"";width:7px;height:7px;border-radius:50%;background:#4ADE80;animation:pulse 1.6s infinite}
@keyframes pulse{0%{box-shadow:0 0 0 0 rgba(74,222,128,.6)}100%{box-shadow:0 0 0 10px rgba(74,222,128,0)}}
.c-body{display:grid;grid-template-columns:1.05fr .95fr;gap:12px;padding:14px}
.c-kpis{grid-column:1/-1;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.kpi{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);border-radius:12px;padding:10px 12px}
.kpi b{font:700 21px var(--font-h);color:#fff;display:block;letter-spacing:-.01em}
.kpi span{font:500 10px var(--font-m);color:#8AB4FF;letter-spacing:.06em;text-transform:uppercase}
.kpi.or b{color:#FFB15C}.kpi.gr b{color:#4ADE80}.kpi.rd b{color:#F87171}
.c-list{display:grid;gap:8px;align-content:start}
.c-row{display:flex;align-items:center;gap:10px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.08);border-radius:10px;padding:8px 10px;font-size:12px;color:#DCE7FF;animation:pprise .7s both}
.c-row:nth-child(2){animation-delay:.15s}.c-row:nth-child(3){animation-delay:.3s}.c-row:nth-child(4){animation-delay:.45s}
.c-row .ic{width:26px;height:26px;border-radius:8px;background:rgba(21,101,216,.35);display:grid;place-items:center;color:#8AB4FF;flex:none}
.c-row .ic svg{width:13px;height:13px}
.c-row .nm{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-weight:500}
.c-row .nm small{display:block;font:500 9.5px var(--font-m);color:#7F94BB;letter-spacing:.02em}
.pill{font:600 9.5px var(--font-m);padding:3px 8px;border-radius:999px;letter-spacing:.05em;white-space:nowrap}
.pill.gr{background:rgba(34,197,94,.18);color:#4ADE80}.pill.or{background:rgba(255,140,26,.22);color:#FFB15C}.pill.rd{background:rgba(239,68,68,.22);color:#F87171}.pill.bl{background:rgba(59,130,246,.25);color:#93C5FD}.pill.gy{background:rgba(255,255,255,.1);color:#B9C8E4}
.c-vis{background:rgba(0,0,0,.2);border:1px solid rgba(255,255,255,.08);border-radius:12px;padding:8px;display:grid;place-items:center;min-height:190px}
.c-vis svg{width:100%;height:auto}
.fcard{position:absolute;background:#fff;color:var(--navy);border-radius:14px;padding:10px 14px;box-shadow:0 20px 40px rgba(0,0,0,.35);display:flex;gap:10px;align-items:center;font-size:12px;animation:scfloat 6s ease-in-out infinite;z-index:3;white-space:nowrap}
.fcard b{font:700 18px var(--font-h);display:block;color:var(--navy);line-height:1.05;letter-spacing:-.01em}
.fcard span{color:var(--mute);font:500 10.5px var(--font-m)}
.fcard .fi{width:34px;height:34px;border-radius:10px;display:grid;place-items:center;color:#fff;background:linear-gradient(135deg,var(--blue),#0B3E9C);flex:none}
.fcard .fi svg{width:16px;height:16px}
.fcard .fi.or{background:linear-gradient(135deg,#FF9A3C,#FF7A00)}.fcard .fi.gr{background:linear-gradient(135deg,#22C55E,#15803D)}
.fcard.f1{top:-28px;right:-6px;animation-delay:.6s}.fcard.f2{bottom:-24px;left:-28px;animation-delay:1.4s}.fcard.f3{top:-56px;left:-30px;animation-delay:2.2s}
.seal{position:absolute;bottom:-40px;right:-16px;width:96px;height:96px;border-radius:50%;background:radial-gradient(circle at 30% 30%,#fff,#DCE7FF);display:grid;place-items:center;text-align:center;font:700 9px/1.3 var(--font-m);color:var(--navy);box-shadow:0 14px 30px rgba(0,0,0,.4);z-index:4;letter-spacing:.06em}
.seal::before{content:"";position:absolute;inset:-5px;border-radius:50%;border:3px dashed var(--orange);animation:rot 24s linear infinite}
.seal svg{width:22px;height:22px;color:var(--blue);margin:0 auto 3px}
@keyframes rot{to{transform:rotate(360deg)}}
/* sections */
.pp-sec{padding:92px 0}
.pp-sec.ice{background:var(--ice)}
.pp-sec.navy{background:var(--navy);color:#fff;position:relative;overflow:hidden}
.pp-sec.navy::before{content:"";position:absolute;width:600px;height:600px;border-radius:50%;background:radial-gradient(circle,rgba(21,101,216,.35),transparent 65%);left:-200px;top:-200px}
.pp-sec.navy .wrap{position:relative}
.sec-h{max-width:780px;margin:0 auto 52px;text-align:center}
.sec-h.left{text-align:left;margin-left:0}
.eyebrow{font:600 12px var(--font-m);letter-spacing:.14em;text-transform:uppercase;color:var(--blue);margin-bottom:14px;display:inline-flex;gap:10px;align-items:center}
.eyebrow::before{content:"";width:22px;height:2px;background:var(--orange)}
.navy .eyebrow{color:#8AB4FF}
.sec-h h2{font-size:clamp(28px,3.4vw,42px);margin-bottom:14px;letter-spacing:-.02em}
.navy h2,.navy h3,.navy h4{color:#fff}
.sec-h p{font-size:17px;color:var(--mute)}.navy .sec-h p{color:#B9C8E4}
.hl{position:relative;display:inline-block;z-index:0}
.hl::after{content:"";position:absolute;left:-2px;right:-2px;bottom:2px;height:12px;width:0;background:rgba(255,140,26,.38);z-index:-1;border-radius:4px;transition:width 1s cubic-bezier(.2,.8,.2,1) .3s}
.in .hl::after{width:calc(100% + 4px)}
/* trust strip */
.pp-trust{background:#fff;border-bottom:1px solid var(--line);padding:26px 0;position:relative;z-index:3}
.pp-trust .wrap{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.tstat{text-align:center;padding:10px;border-right:1px solid var(--line)}
.tstat:last-child{border:0}
.tstat b{font:800 34px var(--font-h);color:var(--navy);display:block;line-height:1.1;letter-spacing:-.02em}
.tstat b em{color:var(--orange);font-style:normal}
.tstat span{font:500 11.5px var(--font-m);color:var(--mute);letter-spacing:.06em;text-transform:uppercase}
/* grids & cards */
.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.grid2{display:grid;grid-template-columns:repeat(2,1fr);gap:22px}.grid4{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
.card{background:#fff;border:1px solid var(--line);border-radius:var(--r);padding:28px;box-shadow:var(--sh);transition:transform .35s,box-shadow .35s,border-color .35s;position:relative;overflow:hidden}
.card:hover{transform:translateY(-6px);box-shadow:var(--sh2);border-color:#BFD3F5}
.card::before{content:"";position:absolute;left:0;top:0;height:3px;width:0;background:linear-gradient(90deg,var(--blue),var(--orange));transition:width .5s}
.card:hover::before{width:100%}
.fic{width:52px;height:52px;border-radius:14px;background:linear-gradient(135deg,var(--soft),#fff);border:1px solid #D5E3F8;display:grid;place-items:center;color:var(--blue);margin-bottom:18px;transition:.35s;flex:none}
.card:hover .fic{background:linear-gradient(135deg,var(--blue),#0B3E9C);color:#fff;transform:rotate(-6deg) scale(1.05);border-color:transparent}
.fic svg{width:24px;height:24px}
.card h3{font-size:19px;margin-bottom:10px}
.card p{color:var(--mute);font-size:15px}
/* solutions hub grid */
.sol-cat{margin-bottom:56px}
.sol-cat:last-child{margin-bottom:0}
.sol-cat .ch{display:flex;align-items:center;gap:16px;margin-bottom:22px;padding-bottom:16px;border-bottom:1px solid var(--line)}
.sol-cat .ch .fic{margin:0;width:48px;height:48px;background:linear-gradient(135deg,var(--blue),#0B3E9C);color:#fff;border:0}
.sol-cat .ch h3{font-size:24px}
.sol-cat .ch p{color:var(--mute);font-size:14.5px}
.sol-cat .ch .cnt{margin-left:auto;font:600 12px var(--font-m);color:var(--blue);background:var(--soft);padding:6px 12px;border-radius:999px;white-space:nowrap}
.sol{display:flex;flex-direction:column;gap:12px;padding:26px;background:#fff;border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh);transition:transform .35s,box-shadow .35s,border-color .35s;position:relative;overflow:hidden;min-height:230px}
.sol::after{content:"";position:absolute;width:160px;height:160px;border-radius:50%;background:radial-gradient(circle,rgba(21,101,216,.16),transparent 65%);right:-60px;top:-60px;transition:.4s}
.sol:hover{transform:translateY(-7px);box-shadow:var(--sh2);border-color:#BFD3F5}
.sol:hover::after{background:radial-gradient(circle,rgba(255,140,26,.28),transparent 65%);transform:scale(1.4)}
.sol .fic{margin:0}
.sol h4{font-size:19px;margin-top:4px}
.sol p{font-size:14.5px;color:var(--mute);flex:1}
.sol .go{display:inline-flex;gap:8px;align-items:center;font:700 13.5px var(--font-b);color:var(--blue);margin-top:4px}
.sol .go svg{width:15px;height:15px;transition:transform .3s}
.sol:hover .go svg{transform:translateX(5px)}
.sol .st{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}
.rtag{font:600 11px var(--font-m);padding:5px 10px;border-radius:999px;letter-spacing:.04em;white-space:nowrap}
.rtag.owned{background:var(--soft);color:var(--blue);border:1px solid #BFD3F5}
.rtag.external{background:#FFF7ED;color:#9A3412;border:1px solid #FDBA74}
.rtag.third{background:#ECFDF5;color:#047857;border:1px solid #A7F3D0}
.chips2{display:flex;gap:6px;flex-wrap:wrap}
.chips2 span{font:500 11.5px var(--font-m);padding:5px 10px;border-radius:8px;background:var(--ice);border:1px solid var(--line);color:var(--mute)}
.sfoot{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:4px;flex-wrap:wrap}
.sol .from{font:600 11px var(--font-m);color:#9A3412;background:#FFF7ED;border:1px solid #FDBA74;padding:4px 9px;border-radius:999px;white-space:nowrap}
.pillar{background:#fff;border:1px solid var(--line);border-radius:var(--r);padding:26px;box-shadow:var(--sh);transition:.35s;position:relative;overflow:hidden;display:flex;flex-direction:column;gap:8px}
.pillar::after{content:"";position:absolute;left:0;right:0;bottom:0;height:4px;background:linear-gradient(90deg,var(--blue),var(--orange));transform:scaleX(0);transform-origin:left;transition:transform .5s}
.pillar:hover{transform:translateY(-6px);box-shadow:var(--sh2)}.pillar:hover::after{transform:scaleX(1)}
.pillar .fic{margin:0 0 6px}
.pillar .pk{font:600 11.5px var(--font-m);color:var(--orange);letter-spacing:.08em;text-transform:uppercase}
.pillar h3{font-size:19px}.pillar p{font-size:14px;color:var(--mute);flex:1}
.pillar ul{display:grid;gap:5px;margin-top:6px}.pillar li{font-size:13.5px;color:var(--navy);display:flex;gap:8px;align-items:center}
.pillar li::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--blue);flex:none}
.ptile{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:18px 20px;background:#fff;border:1px solid var(--line);border-radius:14px;transition:.3s}
.ptile:hover{border-color:var(--orange);transform:translateY(-4px);box-shadow:var(--sh)}
.ptile b{display:block;font:700 15px var(--font-h);color:var(--navy)}.ptile small{font:500 11px var(--font-m);color:var(--mute)}
.ptile .pv{font:800 18px var(--font-h);color:var(--blue);white-space:nowrap;text-align:right;letter-spacing:-.01em}.ptile .pv small{display:block;color:var(--mute)}
.chips{display:flex;gap:8px;flex-wrap:wrap;justify-content:center;margin:-16px 0 44px}
.chips button{font:600 13px var(--font-m);padding:9px 16px;border-radius:999px;border:1px solid var(--line);background:#fff;color:var(--navy);transition:.2s}
.chips button:hover,.chips button.on{background:var(--navy);color:#fff;border-color:var(--navy)}
.sol-cat.hide{display:none}
.sol.hide{display:none}
.sol-grid{margin-top:4px}
/* overview */
.ov{display:grid;grid-template-columns:1.1fr .9fr;gap:56px;align-items:center}
.ov .lead{font-size:18px;color:var(--mute);margin-bottom:22px}
.ov-pts{display:grid;gap:14px}
.ov-pt{display:flex;gap:14px;padding:16px;border-radius:14px;background:var(--ice);border:1px solid var(--line);transition:.3s}
.ov-pt:hover{border-color:var(--blue);transform:translateX(6px)}
.ov-pt .fic{width:44px;height:44px;margin:0}
.ov-pt h4{font-size:16px;margin-bottom:4px}.ov-pt p{font-size:14px;color:var(--mute)}
.ov-panel{background:var(--navy);color:#fff;border-radius:22px;padding:32px;position:relative;overflow:hidden;box-shadow:var(--sh2)}
.ov-panel::after{content:"";position:absolute;width:320px;height:320px;border-radius:50%;background:radial-gradient(circle,rgba(255,140,26,.38),transparent 65%);right:-110px;top:-110px}
.ov-panel h4{color:#fff;font-size:21px;margin-bottom:6px;position:relative}
.ov-panel .pm{font:500 11.5px var(--font-m);color:#8AB4FF;letter-spacing:.08em;margin-bottom:16px;position:relative}
.ov-panel ul{position:relative}
.ov-panel li{display:flex;gap:10px;align-items:flex-start;padding:11px 0;border-bottom:1px solid rgba(255,255,255,.1);font-size:14.5px;color:#DCE7FF}
.ov-panel li:last-child{border:0}
.ov-panel li i{color:#4ADE80;flex:none;margin-top:3px;width:18px;height:18px;border-radius:50%;background:rgba(34,197,94,.18);display:grid;place-items:center}
.ov-panel li i svg{width:10px;height:10px}
/* steps */
.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:22px}
.steps.s3{grid-template-columns:repeat(3,1fr)}
.step{background:#fff;border:1px solid var(--line);border-radius:var(--r);padding:28px 24px;position:relative;box-shadow:var(--sh);transition:.3s}
.step:hover{transform:translateY(-6px);border-color:var(--orange)}
.step .n{font:800 52px var(--font-h);color:var(--soft);position:absolute;right:18px;top:6px;line-height:1;letter-spacing:-.04em}
.step .sn{width:40px;height:40px;border-radius:12px;background:linear-gradient(135deg,var(--blue),#0B3E9C);color:#fff;display:grid;place-items:center;margin-bottom:16px;box-shadow:0 8px 18px rgba(21,101,216,.3)}
.step .sn svg{width:19px;height:19px}
.step h3{font-size:18px;margin-bottom:8px}.step p{color:var(--mute);font-size:14.5px}
.step::after{content:"";position:absolute;right:-22px;top:50%;width:22px;height:2px;background:linear-gradient(90deg,var(--orange),transparent)}
.step:last-child::after{display:none}
/* benefits */
.pp-ben{display:flex;gap:16px;padding:22px;border-radius:var(--r);background:#fff;border:1px solid var(--line);transition:.3s}
.pp-ben:hover{border-color:var(--orange);transform:translateX(6px);box-shadow:var(--sh)}
.pp-ben .fic{margin:0}
.pp-ben h4{font-size:16.5px;margin-bottom:4px}.pp-ben p{font-size:14px;color:var(--mute)}
/* before/after */
.ba{border:1px solid var(--line);border-radius:var(--r);overflow:hidden;background:#fff;box-shadow:var(--sh)}
.ba-h,.ba-r{display:grid;grid-template-columns:1.2fr 1fr 1fr;align-items:center}
.ba-h{background:var(--navy);color:#fff;font:600 12px var(--font-m);letter-spacing:.08em;text-transform:uppercase}
.ba-h div,.ba-r div{padding:15px 20px}
.ba-h .a{color:#FFB15C}
.ba-r{border-top:1px solid var(--line);font-size:15px}
.ba-r:nth-child(odd){background:var(--ice)}
.ba-r .m{font-weight:600;color:var(--navy)}
.ba-r .b{color:#9F1239;display:flex;gap:9px;align-items:center}
.ba-r .a{color:#166534;font-weight:600;display:flex;gap:9px;align-items:center}
.ba-r .b i,.ba-r .a i{width:8px;height:8px;border-radius:50%;background:currentColor;flex:none}
/* pricing */
.pp-plans{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;align-items:stretch;padding-top:14px}
.pp-plan{background:#fff;border:1.5px solid var(--line);border-radius:22px;padding:30px;position:relative;display:flex;flex-direction:column;transition:.35s;box-shadow:var(--sh)}
.pp-plan:hover{transform:translateY(-8px);box-shadow:var(--sh2)}
.pp-plan.pop{border-color:var(--orange);box-shadow:0 24px 60px rgba(255,140,26,.22);transform:scale(1.03)}
.pp-plan.pop:hover{transform:scale(1.03) translateY(-8px)}
.pp-plan .ptag{position:absolute;top:-14px;left:50%;transform:translateX(-50%);background:linear-gradient(90deg,#FF9A3C,#FF7A00);color:#fff;font:700 11px var(--font-m);letter-spacing:.1em;padding:7px 14px;border-radius:999px;text-transform:uppercase;box-shadow:0 8px 20px rgba(255,140,26,.4);white-space:nowrap}
.pp-plan .pn{font:700 22px var(--font-h);color:var(--navy);margin-bottom:6px}
.pp-plan .pd{font-size:13.5px;color:var(--mute);min-height:42px;margin-bottom:14px}
.pp-plan .pr{display:flex;align-items:baseline;gap:6px;margin-bottom:2px}
.pp-plan .pr b{font:800 36px var(--font-h);color:var(--navy);letter-spacing:-.02em}
.pp-plan .pr span{font:500 13px var(--font-m);color:var(--mute)}
.pp-plan .pl{font:500 12px var(--font-m);color:var(--mute);margin-bottom:8px}
.pp-plan .pl s{color:#B91C1C}
.pp-plan .inc{font:600 12px var(--font-m);color:var(--blue);background:var(--soft);border-radius:8px;padding:8px 10px;margin:6px 0 14px;display:inline-block}
.pp-plan .terms{display:flex;gap:6px;margin-bottom:16px}
.pp-plan .terms button{flex:1;font:600 11.5px var(--font-m);padding:7px 4px;border-radius:8px;border:1px solid var(--line);background:#fff;color:var(--navy);transition:.2s;line-height:1.3}
.pp-plan .terms button:hover,.pp-plan .terms button.on{border-color:var(--blue);background:var(--soft);color:var(--blue)}
.pp-plan .terms button small{display:block;font-size:9.5px;color:#15803D;font-weight:700}
.pp-plan ul{display:grid;gap:9px;margin-bottom:22px;flex:1}
.pp-plan li{display:flex;gap:10px;font-size:14px;color:#33415C;align-items:flex-start}
.pp-plan li i{width:18px;height:18px;border-radius:50%;background:#DCFCE7;color:#15803D;display:grid;place-items:center;flex:none;margin-top:2px;transform:scale(0);transition:transform .45s cubic-bezier(.3,1.6,.5,1)}
.pp-plan.in li i,.in .pp-plan li i{transform:scale(1)}
.pp-plan li:nth-child(2) i{transition-delay:.08s}.pp-plan li:nth-child(3) i{transition-delay:.16s}.pp-plan li:nth-child(4) i{transition-delay:.24s}.pp-plan li:nth-child(5) i{transition-delay:.32s}.pp-plan li:nth-child(6) i{transition-delay:.4s}
.pp-plan li i svg{width:10px;height:10px}
.pp-plan .btn{width:100%}
.pv-note{margin:26px auto 0;max-width:820px;text-align:center;font:500 12.5px/1.5 var(--font-m);color:#9A3412;background:#FFF7ED;border:1px dashed #FDBA74;border-radius:10px;padding:10px 16px}
.gst-note{margin-top:10px;text-align:center;font-size:13.5px;color:var(--mute)}
/* table */
.tbl-w{overflow-x:auto;border-radius:var(--r);box-shadow:var(--sh);border:1px solid var(--line)}
.tbl{width:100%;border-collapse:collapse;background:#fff;min-width:640px}
.tbl th,.tbl td{padding:14px 18px;text-align:center;font-size:14px;border-bottom:1px solid var(--line)}
.tbl th{background:var(--navy);color:#fff;font:600 12px var(--font-m);letter-spacing:.08em;text-transform:uppercase}
.tbl th.pop{background:var(--orange)}
.tbl td:first-child,.tbl th:first-child{text-align:left;font-weight:600;color:var(--navy)}
.tbl th:first-child{color:#fff}
.tbl tr:nth-child(even) td{background:var(--ice)}
.tbl tr:last-child td{border:0}
.tbl .y{color:#15803D;font-weight:700}.tbl .n{color:#CBD5E1;font-weight:700}
/* addons */
.addon{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:22px;background:#fff;border:1px solid var(--line);border-radius:var(--r);transition:.3s}
.addon:hover{border-color:var(--blue);transform:translateY(-4px);box-shadow:var(--sh)}
.addon h4{font-size:16px;margin-bottom:4px}.addon p{font-size:13.5px;color:var(--mute)}
.addon .ap{font:700 17px var(--font-h);color:var(--blue);white-space:nowrap;text-align:right;letter-spacing:-.01em}
.addon .ap small{display:block;font:500 11px var(--font-m);color:var(--mute)}
/* use cases */
.pp-usecard{padding:26px;border-radius:var(--r);background:#fff;border:1px solid var(--line);position:relative;overflow:hidden;transition:.35s}
.pp-usecard:hover{background:var(--navy);transform:translateY(-6px);border-color:var(--navy)}
.pp-usecard:hover h4{color:#fff}.pp-usecard:hover p{color:#C9D6EE}
.pp-usecard .fic{margin-bottom:14px}.pp-usecard:hover .fic{background:rgba(255,255,255,.12);color:#FFB15C;border-color:transparent}
.pp-usecard h4{font-size:17px;margin-bottom:6px}.pp-usecard p{font-size:14px;color:var(--mute)}
/* integrations */
.intg{display:flex;flex-wrap:wrap;gap:10px;justify-content:center}
.intg span{font:600 13px var(--font-m);padding:10px 16px;border-radius:999px;background:#fff;border:1px solid var(--line);color:var(--navy);transition:.25s;display:inline-flex;gap:8px;align-items:center}
.intg span::before{content:"";width:8px;height:8px;border-radius:50%;background:linear-gradient(135deg,var(--blue),var(--orange))}
.intg span:hover{border-color:var(--blue);color:var(--blue);transform:translateY(-3px);box-shadow:var(--sh)}
/* why */
.pp-whycard{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);border-radius:var(--r);padding:26px;transition:.3s}
.pp-whycard:hover{background:rgba(255,255,255,.1);transform:translateY(-6px);border-color:rgba(255,140,26,.55)}
.pp-whycard .fic{background:rgba(21,101,216,.3);border-color:rgba(255,255,255,.1);color:#8AB4FF}
.pp-whycard h4{color:#fff;font-size:17px;margin-bottom:6px}.pp-whycard p{color:#B9C8E4;font-size:14px}
/* testimonials */
.pp-tcards{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}
.tc{background:#fff;border:1px solid var(--line);border-radius:var(--r);padding:28px;box-shadow:var(--sh);position:relative;transition:.3s}
.tc:hover{transform:translateY(-6px);box-shadow:var(--sh2)}
.tc .q{font:italic 400 60px var(--font-s);color:var(--orange);line-height:1;position:absolute;top:14px;right:22px;opacity:.35}
.tc .stars{color:var(--orange);font-size:13px;letter-spacing:2px;margin-bottom:12px}
.tc p{font-size:15px;color:#33415C;margin-bottom:18px;font-style:italic}
.tc .who{display:flex;gap:12px;align-items:center}
.tc .av{width:42px;height:42px;border-radius:50%;background:linear-gradient(135deg,var(--blue),#0B3E9C);color:#fff;display:grid;place-items:center;font:700 14px var(--font-h);flex:none}
.tc .who b{display:block;font-size:14px;color:var(--navy)}.tc .who span{font:500 11.5px var(--font-m);color:var(--mute)}
/* faq */
.faq2{max-width:860px;margin:0 auto;display:grid;gap:10px}
.faq-i{background:#fff;border:1px solid var(--line);border-radius:14px;overflow:hidden;transition:.3s}
.faq-i.open{border-color:var(--blue);box-shadow:var(--sh)}
.faq-q{width:100%;display:flex;justify-content:space-between;align-items:center;gap:16px;padding:18px 22px;text-align:left;font:600 16px var(--font-h);color:var(--navy)}
.faq-q i{width:28px;height:28px;border-radius:50%;background:var(--soft);color:var(--blue);display:grid;place-items:center;flex:none;transition:.3s;font-style:normal;font-weight:700;font-family:var(--font-m)}
.faq-i.open .faq-q i{transform:rotate(45deg);background:var(--orange);color:#fff}
.faq-a{max-height:0;overflow:hidden;transition:max-height .4s ease}
.faq-a p{padding:0 22px 20px;color:var(--mute);font-size:15px}
/* blog */
.blog{background:#fff;border:1px solid var(--line);border-radius:var(--r);overflow:hidden;transition:.3s;box-shadow:var(--sh);display:flex;flex-direction:column}
.blog:hover{transform:translateY(-6px);box-shadow:var(--sh2)}
.blog .bi{height:150px;background:linear-gradient(135deg,var(--navy),var(--blue));position:relative;display:grid;place-items:center;color:#fff}
.blog .bi svg{width:44px;height:44px;opacity:.9;position:relative}
.blog .bi::before{content:"";position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.08) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.08) 1px,transparent 1px);background-size:24px 24px}
.blog .bb{padding:22px;display:flex;flex-direction:column;flex:1}
.blog .bt{font:600 11px var(--font-m);color:var(--orange);letter-spacing:.1em;text-transform:uppercase;margin-bottom:8px}
.blog h4{font-size:17px;margin-bottom:8px}.blog p{font-size:14px;color:var(--mute);margin-bottom:14px;flex:1}
.blog .rm{font:600 13px var(--font-b);color:var(--blue);display:inline-flex;gap:6px;align-items:center}
.blog .rm svg{width:14px;height:14px}
/* contact */
.pp-contact{display:grid;grid-template-columns:.9fr 1.1fr;gap:40px;align-items:start}
.cinfo{display:grid;gap:14px}
.cinfo .ci{display:flex;gap:14px;align-items:center;padding:18px;border-radius:14px;background:#fff;border:1px solid var(--line);transition:.3s}
.cinfo .ci:hover{border-color:var(--blue);transform:translateX(6px)}
.cinfo .ci .fic{margin:0;width:44px;height:44px}
.cinfo .ci b{display:block;font-size:15px;color:var(--navy)}.cinfo .ci span{font-size:13.5px;color:var(--mute)}
.cform{background:#fff;border:1px solid var(--line);border-radius:22px;padding:30px;box-shadow:var(--sh2)}
.cform h3{font-size:22px;margin-bottom:6px}.cform>p{color:var(--mute);font-size:14px;margin-bottom:18px}
.cform .fr{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:12px}
.cform input,.cform select,.cform textarea{width:100%;font:400 14px var(--font-b);padding:12px 14px;border:1px solid var(--line);border-radius:10px;background:var(--ice);color:var(--ink);outline:none;transition:.2s}
.cform input:focus,.cform textarea:focus,.cform select:focus{border-color:var(--blue);background:#fff;box-shadow:0 0 0 3px rgba(21,101,216,.12)}
.cform textarea{min-height:100px;resize:vertical;margin-bottom:12px}
.cform .btn{width:100%}
.cform .priv{font-size:12px;color:var(--mute);text-align:center;margin-top:10px}
/* cta */
.cta-wrap{padding:0 0 130px}
.cta{background:linear-gradient(135deg,#041E42 0%,#0A3A80 60%,#1565D8 100%);color:#fff;border-radius:28px;padding:64px 56px;display:grid;grid-template-columns:1.3fr .7fr;gap:30px;align-items:center;position:relative;overflow:hidden;box-shadow:var(--sh2)}
.cta::before{content:"";position:absolute;width:440px;height:440px;border-radius:50%;background:radial-gradient(circle,rgba(255,140,26,.45),transparent 65%);right:-120px;top:-170px;animation:aur2 12s ease-in-out infinite}
.cta::after{content:"";position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.05) 1px,transparent 1px);background-size:40px 40px;pointer-events:none}
.cta h2{color:#fff;font-size:clamp(26px,3vw,38px);margin-bottom:12px;position:relative;z-index:1;letter-spacing:-.02em}
.cta p{color:#C9D6EE;font-size:17px;position:relative;z-index:1}
.cta .hctas{justify-content:flex-end;position:relative;z-index:1}
/* newsletter */
.newsletter{background:var(--ice);border-top:1px solid var(--line);padding:40px 0}
.newsletter .wrap{display:flex;justify-content:space-between;align-items:center;gap:24px;flex-wrap:wrap}
.newsletter h4{font-size:20px}.newsletter p{color:var(--mute);font-size:14px}
.nl-f{display:flex;gap:8px;flex-wrap:wrap}.nl-f input{font:400 14px var(--font-b);padding:12px 16px;border:1px solid var(--line);border-radius:10px;min-width:280px;outline:none;background:#fff}
.nl-f input:focus{border-color:var(--blue)}
/* footer (xcellhost.cloud royal-blue footer) */
.site-foot{background:var(--royal);color:#fff;padding:0 0 28px;position:relative}
.xf-news{background:var(--royal3);border-radius:18px;padding:34px 44px;transform:translateY(-58px);margin-bottom:-14px;box-shadow:0 24px 60px rgba(0,0,0,.3);display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.3fr);gap:30px;align-items:center}
.xf-news h3{color:#fff;font-size:26px;margin-bottom:6px}.xf-news p{color:#BFD3F5;font-size:15px}
.xf-news form{display:flex;gap:12px}.xf-news input{flex:1;padding:18px 22px;border-radius:12px;border:0;font:400 16px var(--font-b);background:#F4F7FB;color:#0B1F4A;outline:none;min-width:0}
.xf-news button{background:var(--royal);color:#fff;font:700 17px var(--font-b);padding:0 34px;border-radius:12px;white-space:nowrap}
.xf-news button:hover{background:#2F6BE8}
.xf-top{display:grid;grid-template-columns:1.15fr .85fr;gap:44px;align-items:start;padding:10px 0 34px}
.xf-brand{display:flex;gap:20px;align-items:center;flex-wrap:wrap}
.xf-logo{background:#fff;border-radius:10px;padding:14px 18px}
.xf-brand .bl b{display:block;font-size:16px;font-weight:700}.xf-brand .bl span{font-size:14px;color:#DCE7FF}
.xf-badge{width:116px;height:116px;border-radius:50%;background:#fff;color:var(--royal);display:grid;place-items:center;text-align:center;font:700 10.5px/1.25 var(--font-h);border:4px solid var(--royal3);margin-left:auto;padding:8px;box-shadow:0 10px 24px rgba(0,0,0,.25)}
.xf-badge svg{width:26px;height:26px;margin:0 auto 2px;color:var(--orange)}
.xf-about{margin-top:26px;font-size:15px;line-height:1.85;text-align:justify;color:#F1F5FF}
.xf-social{display:flex;gap:12px;margin-top:26px;flex-wrap:wrap}
.xf-social a{width:50px;height:50px;border-radius:50%;display:grid;place-items:center;color:#fff;font:700 16px var(--font-h);transition:.25s}
.xf-social a:hover{transform:translateY(-4px)}
.xf-video h3{color:#fff;font-size:32px;margin-bottom:16px;font-weight:700}
.xf-vid{aspect-ratio:16/9;border-radius:18px;background:linear-gradient(135deg,#041E42,#0A3A80 60%,#1565D8);position:relative;overflow:hidden;display:grid;place-items:center;box-shadow:0 22px 50px rgba(0,0,0,.35);cursor:pointer}
.xf-vid::before{content:"";position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.07) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.07) 1px,transparent 1px);background-size:32px 32px}
.xf-vid .vt{position:absolute;left:24px;top:22px;right:24px;font:700 21px var(--font-h);color:#fff;text-shadow:0 2px 8px rgba(0,0,0,.4)}
.xf-vid .vt small{display:block;font:500 13px var(--font-b);color:#BFD3F5;margin-top:4px}
.xf-vid .play{width:86px;height:60px;border-radius:16px;background:#FF0000;display:grid;place-items:center;box-shadow:0 12px 30px rgba(255,0,0,.4);position:relative;transition:.25s}
.xf-vid:hover .play{transform:scale(1.08)}
.xf-vid .play svg{width:30px;height:30px;color:#fff}
.xf-vid .yt{position:absolute;right:26px;bottom:20px;font:700 15px var(--font-b);color:#fff}
.xf-rows{border-top:1px solid rgba(255,255,255,.28)}
.xf-row{display:grid;grid-template-columns:200px 1fr;gap:16px;padding:22px 0;border-bottom:1px solid rgba(255,255,255,.16);align-items:start}
.xf-row h5{font:700 19px var(--font-h);color:#fff;padding-top:4px}
.xf-links{display:flex;flex-wrap:wrap;gap:12px 30px;font-size:16px;align-items:center}
.xf-links a{display:inline-flex;align-items:center;gap:8px}
.xf-links a::before{content:"\u203A";color:#BFD3F5;font-weight:700}
.xf-links a:hover{text-decoration:underline}
.xf-links .hire{background:#E5322D;color:#fff;font-weight:700;padding:8px 18px;border-radius:9px}
.xf-links .hire::before{content:none}
.xf-certs{display:flex;flex-wrap:wrap;gap:10px}
.xf-cert{background:var(--royal2);border-radius:10px;padding:10px 14px;min-width:86px;text-align:center;box-shadow:0 8px 18px rgba(0,0,0,.18);transition:.25s}
.xf-cert:hover{transform:translateY(-4px)}
.xf-cert small{display:block;font:700 9.5px var(--font-m);letter-spacing:.08em;color:#BFD3F5}.xf-cert b{display:block;font:800 21px/1.15 var(--font-h);color:#fff}
.xf-pay{display:flex;flex-wrap:wrap;gap:10px}.xf-pay span{background:#fff;color:var(--royal3);font:700 14px var(--font-b);padding:10px 18px;border-radius:9px}
.xf-prot{display:flex;flex-wrap:wrap;gap:22px}.xf-prot div{background:#fff;color:var(--royal3);border-radius:8px;padding:12px 18px;min-width:140px;text-align:center;box-shadow:0 8px 18px rgba(0,0,0,.18)}
.xf-prot b{display:block;font:800 17px var(--font-h)}.xf-prot small{font:500 10.5px var(--font-m);color:#5B6B85;display:block;margin-top:2px}.xf-prot .ok{color:#15803D;font-weight:700}
.xf-rev{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.xf-rev>div{background:#1748B5;border-radius:12px;padding:14px 18px;display:flex;gap:14px;align-items:center}.xf-rev>div>div{display:flex;flex-direction:column;gap:2px}
.xf-rev .ri{width:42px;height:42px;border-radius:9px;display:grid;place-items:center;font:800 19px var(--font-h);flex:none}
.xf-rev b{display:block;font-size:15px}.xf-rev .st{color:#FFB800;letter-spacing:1px;font-size:11px}.xf-rev span{font-size:12.5px;color:#DCE7FF}.xf-rev .st+span{margin-top:-2px}
.xf-grow{background:#2F6BE8;border-radius:16px;padding:28px 36px;display:flex;justify-content:space-between;align-items:center;gap:20px;margin:28px 0}
.xf-grow h4{color:#fff;font-size:24px;margin-bottom:4px}.xf-grow p{color:#DCE7FF;font-size:15px}
.xf-grow .btn{background:var(--orange);color:#fff;box-shadow:0 10px 24px rgba(255,140,26,.35)}
.xf-bot{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;border-top:1px solid rgba(255,255,255,.28);padding-top:24px;font-size:14px;color:#EAF1FF}
.xf-bot .ids{font:500 13px var(--font-m);display:flex;gap:18px;flex-wrap:wrap}
/* floating widgets */
.wa-fab{position:fixed;left:26px;bottom:26px;width:66px;height:66px;border-radius:50%;background:#25D366;display:grid;place-items:center;color:#fff;box-shadow:0 14px 30px rgba(37,211,102,.45);z-index:90;transition:.25s}
.wa-fab:hover{transform:scale(1.06)}.wa-fab svg{width:32px;height:32px}
.cb-tab{position:fixed;right:0;top:44%;background:var(--orange);color:#fff;writing-mode:vertical-rl;transform:rotate(180deg);padding:20px 13px;border-radius:0 14px 14px 0;font:700 15px var(--font-b);z-index:90;box-shadow:-6px 0 20px rgba(0,0,0,.25);display:flex;gap:12px;align-items:center}
.cb-tab svg{width:18px;height:18px;transform:rotate(180deg)}
.totop{position:fixed;right:26px;bottom:26px;transform:translate(0,80px);width:52px;height:52px;border-radius:14px;background:var(--royal);color:#fff;display:grid;place-items:center;box-shadow:0 12px 26px rgba(31,91,217,.4);z-index:90;transition:.35s;opacity:0}
.totop.show{transform:none;opacity:1}.totop svg{width:20px;height:20px}
/* reveal */
.rv{opacity:0;transform:translateY(26px);transition:opacity .8s cubic-bezier(.2,.8,.2,1),transform .8s cubic-bezier(.2,.8,.2,1);transition-delay:var(--d,0s)}
.rv.in{opacity:1;transform:none}
@keyframes pprise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
/* modal */
.overlay{position:fixed;inset:0;background:rgba(4,30,66,.62);backdrop-filter:blur(4px);z-index:200;opacity:0;visibility:hidden;transition:.3s}
.overlay.show{opacity:1;visibility:visible}
.cfg{position:fixed;left:50%;top:50%;transform:translate(-50%,-46%) scale(.96);width:min(780px,94vw);max-height:92vh;overflow:auto;background:#fff;border-radius:22px;z-index:210;opacity:0;visibility:hidden;transition:.35s cubic-bezier(.2,.8,.2,1);box-shadow:0 40px 100px rgba(0,0,0,.45)}
.cfg.show{opacity:1;visibility:visible;transform:translate(-50%,-50%) scale(1)}
.cfg-h{background:linear-gradient(90deg,#FF9A3C,#FF7A00);color:#fff;padding:18px 24px;display:flex;justify-content:space-between;align-items:center;position:sticky;top:0;z-index:2}
.cfg-h h3{color:#fff;font-size:20px}.cfg-h small{display:block;font:500 11px var(--font-m);opacity:.92;letter-spacing:.06em;margin-top:2px}
.cfg-x{width:34px;height:34px;border-radius:50%;background:rgba(255,255,255,.22);color:#fff;font-size:20px;display:grid;place-items:center;flex:none}
.cfg-b{padding:24px;display:grid;grid-template-columns:1.25fr .75fr;gap:22px}
.cfg-l h4{font:700 11.5px var(--font-m);letter-spacing:.12em;text-transform:uppercase;color:var(--mute);margin:0 0 10px}
.cfg-l h4+.stp{margin-top:0}
.term{display:flex;align-items:center;gap:12px;padding:12px 14px;border:1.5px solid var(--line);border-radius:12px;margin-bottom:8px;cursor:pointer;position:relative;transition:.2s}
.term:hover{border-color:#BFD3F5}
.term.on{border-color:var(--blue);background:var(--soft);box-shadow:0 0 0 3px rgba(21,101,216,.12)}
.term .rd{width:18px;height:18px;border-radius:50%;border:2px solid #CBD5E1;display:grid;place-items:center;flex:none}
.term.on .rd{border-color:var(--blue)}.term.on .rd::after{content:"";width:9px;height:9px;border-radius:50%;background:var(--blue)}
.term .ty{font:700 15px var(--font-h);color:var(--navy);width:70px;flex:none}
.term .tp{flex:1;min-width:0}
.term .tp b{font:700 16px var(--font-h);color:var(--navy)}.term .tp .u{font:500 11px var(--font-m);color:var(--mute)}
.term .tp small{display:block;font:500 11px var(--font-m);color:var(--mute);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.term .tp small s{color:#B91C1C}.term .tp small em{color:#15803D;font-style:normal;font-weight:700}
.term .off{font:700 11px var(--font-m);color:#15803D;background:#DCFCE7;padding:4px 8px;border-radius:999px;white-space:nowrap}
.term .best{position:absolute;top:-9px;right:12px;background:var(--orange);color:#fff;font:700 9.5px var(--font-m);letter-spacing:.1em;padding:3px 8px;border-radius:999px}
.stp{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px 14px;border:1.5px solid var(--line);border-radius:12px;margin:14px 0 8px}
.stp .sl b{display:block;font-size:14px;color:var(--navy)}.stp .sl span{font:500 11px var(--font-m);color:var(--mute)}
.stpc{display:flex;align-items:center;gap:8px;flex:none}
.stpc button{width:32px;height:32px;border-radius:9px;border:1px solid var(--line);background:#fff;font-size:18px;color:var(--navy);display:grid;place-items:center;transition:.2s}
.stpc button:hover{border-color:var(--blue);color:var(--blue);background:var(--soft)}
.stpc b{min-width:34px;text-align:center;font:700 16px var(--font-h);color:var(--navy)}
.cfg-r{display:grid;gap:12px;align-content:start}
.cfg-badge{border:1px solid var(--line);border-radius:14px;padding:16px;text-align:center;background:var(--ice)}
.cfg-badge .shl{width:64px;height:64px;margin:0 auto 8px;border-radius:50%;background:linear-gradient(135deg,var(--blue),#0B3E9C);display:grid;place-items:center;color:#fff;box-shadow:0 10px 24px rgba(21,101,216,.35)}
.cfg-badge .shl svg{width:30px;height:30px}
.cfg-badge b{display:block;font:700 13px var(--font-h);color:var(--navy)}.cfg-badge span{font:500 10.5px var(--font-m);color:var(--mute)}
.cfg-sum{border:1.5px solid var(--line);border-radius:14px;padding:16px;background:#fff}
.cfg-sum .r{display:flex;justify-content:space-between;font-size:13.5px;color:var(--mute);padding:6px 0;border-bottom:1px dashed var(--line)}
.cfg-sum .r b{color:var(--navy)}
.cfg-sum .tot{display:flex;justify-content:space-between;align-items:baseline;padding-top:12px}
.cfg-sum .tot span{font:700 11.5px var(--font-m);color:var(--mute);letter-spacing:.08em}
.cfg-sum .tot b{font:800 28px var(--font-h);color:var(--navy);letter-spacing:-.02em}
.cfg-sum .gst{font:500 11px var(--font-m);color:var(--mute);text-align:right}
.cfg-r .btn{width:100%}
.cfg-note{font:500 11px/1.5 var(--font-m);color:var(--mute);text-align:center}
/* cart */
.cart{position:fixed;top:0;right:0;height:100vh;width:min(430px,94vw);background:#fff;z-index:220;transform:translateX(100%);transition:transform .4s cubic-bezier(.2,.8,.2,1);display:flex;flex-direction:column;box-shadow:-20px 0 60px rgba(0,0,0,.25)}
.cart.show{transform:none}
.cart-h{display:flex;justify-content:space-between;align-items:center;padding:20px 22px;border-bottom:1px solid var(--line);background:var(--navy);color:#fff}
.cart-h h3{color:#fff;font-size:18px}.cart-h small{font:500 11px var(--font-m);color:#8AB4FF;display:block}
.cart-items{flex:1;overflow:auto;padding:16px 22px;display:grid;gap:12px;align-content:start}
.ci-empty{text-align:center;color:var(--mute);padding:40px 10px;font-size:14px;line-height:1.7}
.ci{border:1px solid var(--line);border-radius:14px;padding:14px;display:grid;grid-template-columns:1fr auto;gap:8px}
.ci b{font-size:14px;color:var(--navy)}.ci small{display:block;font:500 11px var(--font-m);color:var(--mute);margin-top:2px}
.ci .cp{font:700 15px var(--font-h);color:var(--navy);text-align:right}
.ci .cq{display:flex;align-items:center;gap:6px;margin-top:8px}
.ci .cq button{width:26px;height:26px;border-radius:7px;border:1px solid var(--line);background:#fff;color:var(--navy)}
.ci .cq b{min-width:22px;text-align:center;font-size:13px}
.ci .rm{grid-column:2;justify-self:end;font:500 11px var(--font-m);color:#B91C1C}
.cart-f{border-top:1px solid var(--line);padding:18px 22px;background:var(--ice)}
.cart-f .r{display:flex;justify-content:space-between;font-size:13.5px;color:var(--mute);padding:4px 0}
.cart-f .r.t{font:700 18px var(--font-h);color:var(--navy);padding-top:10px;border-top:1px solid var(--line);margin-top:6px}
.cart-f .btn{width:100%;margin-top:12px}
.cart-f .gn{font:500 11px var(--font-m);color:var(--mute);text-align:center;margin-top:8px}
.toast{position:fixed;bottom:24px;left:50%;transform:translate(-50%,20px);background:var(--navy);color:#fff;padding:12px 20px;border-radius:12px;font:600 14px var(--font-b);box-shadow:var(--sh2);z-index:300;opacity:0;visibility:hidden;transition:.3s;display:flex;gap:10px;align-items:center;max-width:92vw}
.toast.show{opacity:1;visibility:visible;transform:translate(-50%,0)}
.toast i{width:22px;height:22px;border-radius:50%;background:#22C55E;display:grid;place-items:center;font-style:normal;font-size:12px;flex:none}
body.lock{overflow:hidden}

/* agent network diagram */
.agentnet,.dg{position:relative;width:100%;aspect-ratio:600/520;max-width:640px;margin:0 auto;perspective:1200px}
.dg .an-stage svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.hot{cursor:pointer;transition:filter .3s}
.hot .hb{transition:stroke .3s,filter .3s}
.hot:hover,.hot.on{filter:drop-shadow(0 0 9px rgba(255,140,26,.85))}
.hot:hover .hb,.hot.on .hb{stroke:#FFB15C!important}.hot.on .hb-keep{filter:brightness(1.25)}
.hot:focus{outline:none}
.an-stage{position:absolute;inset:0;transform-style:preserve-3d;transition:transform .35s ease-out}
.an-svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.an-link{fill:none;stroke:rgba(138,180,255,.3);stroke-width:1.5;transition:stroke .3s,stroke-width .3s}
.an-link.hot{stroke:#FFB15C;stroke-width:2.5;filter:drop-shadow(0 0 6px rgba(255,140,26,.9))}
.an-core{position:absolute;left:50%;top:48%;width:118px;height:118px;transform:translate(-50%,-50%);border-radius:50%;display:grid;place-items:center;text-align:center;color:#fff;background:radial-gradient(circle at 35% 30%,#3B82F6,#0B3E9C 70%);box-shadow:0 0 0 1px rgba(255,255,255,.22),0 20px 50px rgba(0,0,0,.45),0 0 70px rgba(21,101,216,.6);z-index:2}
.an-core svg{width:30px;height:30px;margin:0 auto 4px}
.an-core b{display:block;font:700 11px/1.2 var(--font-h)}
.an-core small{font:500 8.5px var(--font-m);color:#BFD3F5;letter-spacing:.08em}
.an-ring{position:absolute;left:50%;top:48%;border-radius:50%;border:1px dashed rgba(138,180,255,.35);transform:translate(-50%,-50%);pointer-events:none}
.an-ring.r1{width:172px;height:172px;animation:anrot 30s linear infinite}
.an-ring.r2{width:224px;height:224px;border-style:solid;border-color:rgba(138,180,255,.12);animation:anrot 45s linear infinite reverse}
@keyframes anrot{to{transform:translate(-50%,-50%) rotate(360deg)}}
.an-pulse{position:absolute;left:50%;top:48%;width:118px;height:118px;border-radius:50%;transform:translate(-50%,-50%);border:2px solid rgba(138,180,255,.6);animation:anpulse 2.6s ease-out infinite;pointer-events:none}
.an-pulse.p2{animation-delay:1.3s}
@keyframes anpulse{0%{transform:translate(-50%,-50%) scale(1);opacity:.8}100%{transform:translate(-50%,-50%) scale(2.6);opacity:0}}
.an-node{position:absolute;transform:translate(-50%,-50%);display:flex;align-items:center;gap:8px;padding:6px 12px 6px 7px;border-radius:999px;background:rgba(4,30,66,.78);border:1px solid rgba(138,180,255,.38);color:#fff;font:600 11.5px/1.15 var(--font-h);white-space:nowrap;cursor:pointer;backdrop-filter:blur(8px);box-shadow:0 10px 30px rgba(0,0,0,.35);transition:transform .3s,box-shadow .3s,border-color .3s,background .3s;z-index:3;animation:nfloat 6s ease-in-out infinite}
.an-node .ni{width:26px;height:26px;border-radius:50%;display:grid;place-items:center;flex:none;color:#fff}
.an-node .ni svg{width:13px;height:13px}
.an-node small{display:block;font:500 8.5px var(--font-m);color:#8AB4FF;letter-spacing:.06em;text-transform:uppercase}
.c-infra .ni,.ni.c-infra{background:linear-gradient(135deg,#3B82F6,#1049B3)}.c-brand .ni,.ni.c-brand{background:linear-gradient(135deg,#FF9A3C,#FF6A00)}.c-risk .ni,.ni.c-risk{background:linear-gradient(135deg,#22C55E,#15803D)}.c-human .ni,.ni.c-human{background:linear-gradient(135deg,#A78BFA,#6D28D9)}
.an-node:hover,.an-node.on{transform:translate(-50%,-50%) scale(1.1);border-color:#FFB15C;background:rgba(21,101,216,.6);box-shadow:0 14px 40px rgba(0,0,0,.45),0 0 30px rgba(255,140,26,.4);animation-play-state:paused;z-index:4}
@keyframes nfloat{0%,100%{margin-top:0}50%{margin-top:-6px}}
.an-glow{position:absolute;width:260px;height:260px;border-radius:50%;background:radial-gradient(circle,rgba(255,140,26,.22),transparent 60%);pointer-events:none;transform:translate(-50%,-50%);opacity:0;transition:opacity .3s;z-index:1}
.an-info{position:absolute;left:-30px;top:-26px;width:262px;background:#fff;color:var(--navy);border-radius:16px;padding:13px 15px;box-shadow:0 24px 50px rgba(0,0,0,.42);z-index:6}
.an-info.flash{animation:infoflash .5s}
@keyframes infoflash{0%{transform:scale(.96);opacity:.5}100%{transform:none;opacity:1}}
.an-info .ih{display:flex;gap:10px;align-items:center;margin-bottom:7px}
.an-info .ih .ni{width:36px;height:36px;border-radius:10px;display:grid;place-items:center;color:#fff;flex:none}
.an-info .ih .ni svg{width:18px;height:18px}
.an-info .ih b{display:block;font:700 14px var(--font-h)}.an-info .ih span{font:500 9.5px var(--font-m);color:var(--mute);letter-spacing:.06em;text-transform:uppercase}
.an-info p{font-size:12px;color:var(--mute);margin-bottom:9px;line-height:1.45}
.an-info .im{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-bottom:9px}
.an-info .im div{background:var(--ice);border-radius:8px;padding:5px 7px}
.an-info .im b{display:block;font:700 13px var(--font-h);color:var(--navy)}.an-info .im span{font:500 8.5px var(--font-m);color:var(--mute);text-transform:uppercase;letter-spacing:.04em}
.an-info a{font:700 12.5px var(--font-b);color:var(--blue);display:inline-flex;gap:6px;align-items:center}
.an-info a svg{width:13px;height:13px}
.an-tick{position:absolute;right:-24px;bottom:-18px;background:rgba(4,30,66,.88);border:1px solid rgba(138,180,255,.4);color:#DCE7FF;border-radius:999px;padding:7px 13px;font:500 10.5px var(--font-m);display:flex;gap:8px;align-items:center;z-index:6;backdrop-filter:blur(6px);max-width:380px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.an-tick i{width:7px;height:7px;border-radius:50%;background:#4ADE80;animation:pulse 1.6s infinite;flex:none}
.an-tick span{overflow:hidden;text-overflow:ellipsis}
/* ghost cursor (auto demo) */
.ghost{position:absolute;left:0;top:0;z-index:20;pointer-events:none;transition:transform 1s cubic-bezier(.65,0,.35,1),opacity .4s;opacity:0;filter:drop-shadow(0 4px 8px rgba(0,0,0,.55));transform:translate(50%,50%)}
.ghost.show{opacity:1}
.ghost svg{width:22px;height:26px;display:block}
.ghost .rp{position:absolute;left:-12px;top:-12px;width:28px;height:28px;border-radius:50%;border:2px solid #FFB15C;opacity:0;transform:scale(.4)}
.ghost.click .rp{animation:gclick .6s ease-out}
.ghost.click svg{animation:gpress .3s}
@keyframes gclick{0%{opacity:.9;transform:scale(.4)}100%{opacity:0;transform:scale(1.7)}}
@keyframes gpress{0%,100%{transform:scale(1)}50%{transform:scale(.82)}}
.hvis .console .c-row{transition:transform .3s,border-color .3s,background .3s}
.hvis .console .c-row.on{border-color:#FFB15C;background:rgba(255,140,26,.16);transform:translateX(4px)}
.hvis .console .c-row.on .pill{box-shadow:0 0 0 2px rgba(255,177,92,.45)}
@media(max-width:1100px){.agentnet,.dg{max-width:560px}}
@media(max-width:860px){.agentnet,.dg{max-width:100%;margin-top:120px}.an-info{left:0;top:-112px;width:100%;position:absolute}.an-tick{display:none}.an-node{font-size:10px;padding:4px 9px 4px 5px}.an-node small{display:none}.an-node .ni{width:22px;height:22px}}
/* motion prefs */
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}.rv{opacity:1;transform:none}.pp-plan li i{transform:scale(1)}.hl::after{width:100%}}
/* responsive */
@media(max-width:1100px){.mm{width:680px;grid-template-columns:repeat(2,1fr)}.pp-hero .wrap{grid-template-columns:1fr;gap:56px}.hvis{max-width:600px;margin:10px auto 0}.grid4{grid-template-columns:repeat(2,1fr)}.steps{grid-template-columns:repeat(2,1fr)}.step::after{display:none}.site-foot .cols{grid-template-columns:1fr 1fr 1fr}.cta{grid-template-columns:1fr;padding:44px 32px}.cta .hctas{justify-content:flex-start}.ov{grid-template-columns:1fr}}
@media(max-width:1800px){.utility .u-l a:nth-child(n+10){display:none}}
@media(max-width:1700px){.nav>li>a{padding:9px 8px;font-size:14px}.logo .lg-mark{width:166px;height:82px}.utility .u-l a:nth-child(n+9){display:none}}
@media(max-width:1500px){.hicon.docs,.btn-login{display:none}.nav>li>a{padding:8px 7px;font-size:13.5px}.logo .lg-mark{width:150px;height:74px}.utility .u-l a:nth-child(n+8){display:none}.site-head .wide{height:88px}}
@media(max-width:1300px){.hicon.search{display:none}.nav>li>a{padding:8px 6px;font-size:13px}.utility .u-l a:nth-child(n+6){display:none}}
@media(max-width:1100px){.nav{display:none}.burger{display:grid}}
@media(max-width:860px){.nav,.utility .u-l{display:none}.burger{display:grid}.utility .u-r .lang,.utility .moon{display:none}.xf-news{grid-template-columns:minmax(0,1fr);padding:24px;transform:translateY(-40px)}.xf-news form{flex-wrap:wrap}.xf-news button{width:100%;padding:16px}.xf-top{grid-template-columns:1fr}.xf-row{grid-template-columns:1fr}.xf-rev{grid-template-columns:1fr}.xf-grow{flex-direction:column;align-items:flex-start}.hstats{gap:24px}.hstats div b{font-size:30px}.cb-tab{display:none}.wa-fab{width:56px;height:56px;left:16px;bottom:16px}.site-head.nav-open .nav{display:flex!important;flex-direction:column;align-items:stretch;position:absolute;top:100%;left:0;right:0;background:#fff;padding:12px;border-bottom:1px solid var(--line);box-shadow:var(--sh2);max-height:80vh;overflow:auto}.site-head.nav-open .nav>li>a{padding:12px 14px}.mm{position:static;transform:none;width:100%;grid-template-columns:1fr;opacity:1;visibility:visible;box-shadow:none;border:0;padding:6px 14px 12px;display:none;margin:0}.has-mm.open .mm{display:grid}.h-act .btn-signup{display:none}.grid3,.grid2,.grid4,.pp-plans,.pp-tcards,.steps,.pp-contact{grid-template-columns:1fr}.pp-trust .wrap{grid-template-columns:repeat(2,1fr)}.tstat:nth-child(2){border:0}.pp-plan.pop{transform:none}.pp-plan.pop:hover{transform:translateY(-8px)}.cfg-b{grid-template-columns:1fr}.ba-h{display:none}.ba-r{grid-template-columns:1fr;padding:10px 0}.ba-r div{padding:5px 18px}.ba-r .m{font-size:13px;letter-spacing:.04em;text-transform:uppercase;color:var(--mute)}.fcard.f3{display:none}.site-foot .cols{grid-template-columns:1fr 1fr}.pp-hero{padding:56px 0 76px;min-height:0}.pp-sec{padding:64px 0}.cform .fr{grid-template-columns:1fr}.sol-cat .ch{flex-wrap:wrap}.c-body{grid-template-columns:1fr}}

.wt-hero{background:radial-gradient(1200px 640px at 20% 10%,#06371F 0%,#04140A 60%,#020A05 100%)}
.wt-hero .h1b{background:none;-webkit-text-fill-color:#4ADE80;color:#4ADE80}
.wt-hero .aur.a1{background:#16A34A}.wt-hero .aur.a2{background:#0EA5E9;opacity:.25}
.wt-hero .btn-primary{background:linear-gradient(135deg,#22C55E,#15803D);box-shadow:0 10px 26px rgba(34,197,94,.4)}
.wt-hero .eyeb{color:#4ADE80}
.wt-hero .hstats div::after{background:#22C55E}
.wt-hero .an-info .ih .ni{background:linear-gradient(135deg,#22C55E,#15803D)!important}
.wt-hero .hot:hover,.wt-hero .hot.on{filter:drop-shadow(0 0 9px rgba(74,222,128,.9))}
.wt-hero .hot:hover .hb,.wt-hero .hot.on .hb{stroke:#4ADE80!important}
.wt-hero .an-tick i{background:#4ADE80}
/* marquee */
.wmq{display:grid;gap:14px;overflow:hidden;-webkit-mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent);mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent)}
.wmq-row{overflow:hidden}
.wmq-track{display:flex;gap:12px;width:max-content;animation:wmq 42s linear infinite}
.wmq-track.rev{animation-direction:reverse;animation-duration:52s}
.wmq:hover .wmq-track{animation-play-state:paused}
@keyframes wmq{to{transform:translateX(-50%)}}
.wsrc{display:inline-flex;align-items:center;gap:9px;white-space:nowrap;padding:12px 20px;border-radius:999px;background:#fff;border:1px solid var(--line);font:600 14px var(--font-b);color:var(--navy);box-shadow:var(--sh)}
.wsrc i{width:9px;height:9px;border-radius:50%;flex:none}
/* pipeline / feed */
.wf-wrap{display:grid;grid-template-columns:.95fr 1.05fr;gap:48px;align-items:center}
.wf-copy h2{font-size:clamp(26px,3vw,40px);margin-bottom:14px;letter-spacing:-.02em}
.wf-copy>p{font-size:17px;color:var(--mute);margin-bottom:20px}
.wf-list{display:grid;gap:12px}
.wf-list li{display:flex;gap:12px;font-size:15px;color:#33415C;line-height:1.5}
.wf-list li i{width:9px;height:9px;border-radius:50%;background:var(--green);flex:none;margin-top:7px}
.wf-list b{color:var(--navy);font-weight:700}
.wf-console{background:#041226;border:1px solid rgba(74,222,128,.22);border-radius:16px;overflow:hidden;box-shadow:0 30px 70px rgba(0,0,0,.4)}
.wf-bar{display:flex;align-items:center;gap:7px;padding:12px 16px;border-bottom:1px solid rgba(255,255,255,.08);background:rgba(0,0,0,.3)}
.wf-bar i{width:10px;height:10px;border-radius:50%}
.wf-bar .wf-t{margin-left:8px;font:600 11.5px var(--font-m);color:#7F94BB;letter-spacing:.06em}
.wf-bar .wf-live{margin-left:auto;font:700 10px var(--font-m);color:#4ADE80;display:flex;gap:6px;align-items:center;letter-spacing:.1em}
.wf-bar .wf-live::before{content:"";width:7px;height:7px;border-radius:50%;background:#4ADE80;animation:pulse 1.6s infinite}
.wf-scroll{height:420px;overflow:hidden;position:relative;-webkit-mask-image:linear-gradient(180deg,transparent,#000 8%,#000 88%,transparent);mask-image:linear-gradient(180deg,transparent,#000 8%,#000 88%,transparent)}
.wf-stream{display:flex;flex-direction:column;animation:wfscroll 26s linear infinite}
.wf-scroll:hover .wf-stream{animation-play-state:paused}
@keyframes wfscroll{from{transform:translateY(0)}to{transform:translateY(-50%)}}
.wf-row{padding:13px 18px;border-bottom:1px solid rgba(255,255,255,.06);font-family:var(--font-m)}
.wf-main{display:flex;gap:10px;align-items:flex-start;margin:2px 0 4px}
.wf-time{font-size:11px;color:#4ADE80;letter-spacing:.04em}
.wf-sev{font:700 9.5px var(--font-m);padding:2px 8px;border-radius:5px;border:1px solid;letter-spacing:.06em;flex:none;background:rgba(255,255,255,.04)}
.wf-msg{font-size:12.5px;color:#DCE7FF;line-height:1.4}
.wf-meta{display:flex;gap:8px;font-size:10.5px}
.wf-tool{color:#8AB4FF}.wf-client{color:#7F94BB}
@media(prefers-reduced-motion:reduce){.wmq-track,.wf-stream{animation:none}}
@media(max-width:960px){.wf-wrap{grid-template-columns:1fr;gap:28px}.wf-scroll{height:340px}}

/* Keep the marked Trust Watch hero content on one desktop line. */
.wt-hero h1{
  font-size:clamp(38px,3.2vw,58px);
  white-space:nowrap;
}
.wt-hero .hstats{
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:24px;
}
@media(max-width:640px){
  .wt-hero h1{white-space:normal}
  .wt-hero .hstats{grid-template-columns:repeat(2,minmax(0,1fr))}
}

/* XcellHost default product-page hero buttons. */
.wt-hero .default-hero-ctas{gap:10px}
.wt-hero .default-hero-ctas .btn{padding:12px 18px}
.wt-hero .default-hero-ctas .ppd-info{
  background:linear-gradient(135deg,#2F7BEF,#1049B3);
  border:1.5px solid transparent;
  color:#fff;
  box-shadow:0 10px 26px rgba(21,101,216,.35);
}
.wt-hero .default-hero-ctas .ppd-pres{
  border:1.5px solid rgba(255,255,255,.35);
  color:#fff;
  background:rgba(255,255,255,.06);
  backdrop-filter:blur(6px);
}
.wt-hero .default-hero-ctas .ppd-info:hover,
.wt-hero .default-hero-ctas .ppd-pres:hover{transform:translateY(-2px)}
.wt-hero .default-hero-ctas .ppd-pres:hover{background:rgba(255,255,255,.14)}
.wt-hero .default-hero-ctas .btn-primary{
  background:linear-gradient(135deg,#FF9A3C,#FF7A00);
  box-shadow:0 10px 26px rgba(255,140,26,.38);
}

/* four pillars */
.wp-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}
.wp-card{position:relative;background:#0A1F14;border:1px solid rgba(74,222,128,.18);border-radius:18px;padding:30px;transition:.35s;overflow:hidden}
.wp-card:hover{transform:translateY(-6px);border-color:rgba(74,222,128,.5);box-shadow:0 22px 55px rgba(0,0,0,.4)}
.wp-num{font:700 13px var(--font-m);color:#4ADE80;letter-spacing:.1em}
.wp-ic{display:grid;place-items:center;width:52px;height:52px;border-radius:14px;background:rgba(34,197,94,.16);color:#4ADE80;margin:16px 0 16px;transition:.35s}
.wp-card:hover .wp-ic{background:#16A34A;color:#fff}
.wp-ic svg{width:24px;height:24px}
.wp-card h3{color:#fff;font-size:21px;margin-bottom:10px}
.wp-card p{color:#9FB3C9;font-size:15px;line-height:1.6;margin-bottom:18px}
.wp-chips{display:flex;flex-wrap:wrap;gap:8px}
.wp-chip{font:600 12px var(--font-m);color:#B9C8E4;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.12);padding:6px 12px;border-radius:999px}
@media(max-width:860px){.wp-grid{grid-template-columns:1fr}}
/* signal sources */
.ws-grid{align-items:stretch}
.ws-card{background:#0A1F14;border:1px solid rgba(74,222,128,.18);border-radius:16px;padding:24px;transition:.3s}
.ws-card:hover{transform:translateY(-5px);border-color:rgba(74,222,128,.5);box-shadow:0 18px 45px rgba(0,0,0,.35)}
.ws-head{display:flex;gap:14px;align-items:center;margin-bottom:18px}
.ws-ic{width:46px;height:46px;border-radius:12px;background:rgba(34,197,94,.16);color:#4ADE80;display:grid;place-items:center;flex:none}
.ws-ic svg{width:22px;height:22px}
.ws-cat{display:block;font:700 10.5px var(--font-m);letter-spacing:.1em;text-transform:uppercase;color:#4ADE80}
.ws-head b{color:#fff;font:700 16px var(--font-h)}
.ws-rows{display:grid;gap:12px}
.ws-row{display:flex;align-items:center;gap:10px;font-size:14px}
.ws-dot{width:8px;height:8px;border-radius:50%;flex:none}
.ws-dot.live{background:#4ADE80}.ws-dot.p2{background:#8AB4FF}.ws-dot.p3{background:#A78BFA}.ws-dot.na{background:#94A3B8}
.ws-name{color:#DCE7FF;flex:1}
.ws-tag{font:600 11px var(--font-m);white-space:nowrap}
.ws-tag.live{color:#4ADE80}.ws-tag.p2{color:#8AB4FF}.ws-tag.p3{color:#A78BFA}.ws-tag.na{color:#94A3B8}
/* roadmap */
.wr-grid{align-items:stretch}
.wr-card{background:#0A1F14;border:1px solid rgba(255,255,255,.1);border-radius:16px;padding:26px;transition:.3s;display:flex;flex-direction:column}
.wr-card.live{border-color:rgba(74,222,128,.45)}.wr-card.prog{border-color:rgba(255,177,92,.45)}
.wr-card:hover{transform:translateY(-6px);box-shadow:0 20px 50px rgba(0,0,0,.4)}
.wr-ph{font:700 11px var(--font-m);letter-spacing:.12em;text-transform:uppercase;color:#7F94BB}
.wr-badge{align-self:flex-start;font:700 10.5px var(--font-m);letter-spacing:.06em;padding:5px 12px;border-radius:999px;margin:12px 0 16px}
.wr-badge.live{background:rgba(34,197,94,.18);color:#4ADE80}
.wr-badge.prog{background:rgba(255,177,92,.18);color:#FFB15C}
.wr-badge.soon{background:rgba(255,255,255,.08);color:#B9C8E4}
.wr-badge.plan{background:rgba(255,255,255,.08);color:#B9C8E4}
.wr-card h3{color:#fff;font-size:19px;margin-bottom:16px}
.wr-card ul{display:grid;gap:10px;list-style:none;padding:0}
.wr-card li{position:relative;padding-left:18px;font-size:13.5px;color:#9FB3C9;line-height:1.4}
.wr-card li::before{content:"";position:absolute;left:0;top:7px;width:6px;height:6px;border-radius:50%;background:#4ADE80}
.wr-card.prog li::before{background:#FFB15C}.wr-card.soon li::before,.wr-card.plan li::before{background:#64748B}
@media(max-width:1000px){.wr-grid,.ws-grid{grid-template-columns:1fr 1fr}}
@media(max-width:640px){.wr-grid,.ws-grid{grid-template-columns:1fr}}
.wt-hero{background:radial-gradient(1200px 640px at 20% 10%,#06371F 0%,#04140A 60%,#020A05 100%)}
.wt-hero .h1b{background:none;-webkit-text-fill-color:#4ADE80;color:#4ADE80}
.wt-hero .aur.a1{background:#16A34A}.wt-hero .aur.a2{background:#0EA5E9;opacity:.25}
.wt-hero .btn-primary{background:linear-gradient(135deg,#22C55E,#15803D);box-shadow:0 10px 26px rgba(34,197,94,.4)}
.wt-hero .eyeb{color:#4ADE80}
.wt-hero .hstats div::after{background:#22C55E}
.wt-hero .an-info .ih .ni{background:linear-gradient(135deg,#22C55E,#15803D)!important}
.wt-hero .hot:hover,.wt-hero .hot.on{filter:drop-shadow(0 0 9px rgba(74,222,128,.9))}
.wt-hero .hot:hover .hb,.wt-hero .hot.on .hb{stroke:#4ADE80!important}
.wt-hero .an-tick i{background:#4ADE80}


/* Use compact, consistent spacing between all Trust Watch sections. */
.pp-sec {
  padding-top: 56px;
  padding-bottom: 56px;
}

/* Keep the overview introduction full-width above its two-column details. */
#overview .ov {
  align-items: start;
  column-gap: 56px;
  row-gap: 24px;
}
#overview .ov > div:first-child {
  display: contents;
}
#overview .ov .sec-h,
#overview .ov .lead {
  grid-column: 1 / -1;
  max-width: none;
}
#overview .ov .sec-h {
  margin-bottom: 0;
}
#overview .ov .lead {
  margin-bottom: 8px;
}
#overview .ov-pts {
  grid-column: 1;
}
#overview .ov-panel {
  grid-column: 2;
  grid-row: 4;
}
@media (max-width: 1100px) {
  #overview .ov {
    grid-template-columns: 1fr;
  }
  #overview .ov-panel {
    grid-column: 1;
    grid-row: auto;
  }
}
@media (max-width: 860px) {
  .pp-sec {
    padding-top: 44px;
    padding-bottom: 44px;
  }
  .pp-hero .agentnet {
    margin-top: 0;
  }
}
`;
