  productTourSlides = computed(() => {
    const view = this.view();
    if (!view)
      return [];
    if (this.slug() === "microsoft-security-posture-management")
      return this.microsoftSecurityPostureTourSlides;
    if (this.isCloudBackup())
      return this.cloudBackupTourSlides;
    if (this.isCloudDrive())
      return this.cloudDriveTourSlides;
    if (this.slug() === "smb-cyber-security-appliance")
      return this.smbCyberTourSlides;
    if (this.isWhatsAppSmb())
      return this.whatsAppSmbTourSlides;
    if (view.name === "Acronis True Image")
      return this.acronisTrueImageTourSlides;
    if (view.name === "Microsoft 365 Backup")
      return this.microsoft365BackupTourSlides;
    if (this.isVmc())
      return this.vmcTourSlides;
    if (this.isCmc())
      return this.cmcTourSlides;
    if (this.isTsplusServerMonitoring())
      return this.tsplusServerMonitoringTourSlides;
    if (this.isTsplusRemoteSupport())
      return this.tsplusRemoteSupportTourSlides;
    if (this.isTsplusAdvancedSecurity())
      return this.tsplusAdvancedSecurityTourSlides;
    if (this.isTsplusRemoteAccess())
      return this.tsplusRemoteAccessTourSlides;
    if (this.isResellerProgram())
      return this.resellerProgramTourSlides;
    if (this.isManagedAws())
      return this.managedAwsTourSlides;
    if (this.isManagedAzure())
      return this.managedAzureTourSlides;
    if (view.name === "Scrutiny DLP")
      return this.scrutinyDlpTourSlides;
    const candidates = [];
    if (this.isTally()) {
      candidates.push({ title: "Tally cloud remote desktop", description: "Access TallyPrime Edit Log, Tally.ERP 9 and your files from the TSplus Remote App launcher.", image: "/assets/images/tally-cloud-tour-1.png" }, { title: "Tally remote application workspace", description: "View the remote workspace with shortcuts for your desktop folder, accounting applications and exported files.", image: "/assets/images/tally-cloud-tour-2.png" });
    }
    const add = (title, description, image) => {
      if (!image || candidates.some((slide) => slide.image === image))
        return;
      candidates.push({ title, description, image });
    };
    add(`${view.name} overview`, view.tagline, view.heroImage);
    add(view.featureSpotlight?.title ?? "Feature spotlight", view.featureSpotlight?.body ?? view.overview, view.featureSpotlight?.image);
    add(view.featureDetail?.title ?? "Product capabilities", view.featureDetail?.bullets.join(" ") ?? view.overview, view.featureDetail?.image);
    add(view.frameworkSection?.title ?? "Product framework", view.frameworkSection?.subtitle ?? view.overview, view.frameworkSection?.image);
    add("Framework detail", view.frameworkSection?.subtitle ?? view.overview, view.frameworkSection?.secondaryImage);
    add("Framework overview", view.frameworkSection?.subtitle ?? view.overview, view.frameworkSection?.tertiaryImage);
    add(view.advancedSection?.title ?? "Advanced capabilities", view.advancedSection?.body ?? view.overview, view.advancedSection?.image);
    add("Advanced feature detail", view.advancedSection?.body ?? view.overview, view.advancedSection?.secondaryImage);
    add("Advanced feature overview", view.advancedSection?.body ?? view.overview, view.advancedSection?.tertiaryImage);
    for (const item of view.benefitGrid)
      add(item.title, item.body ?? view.overview, item.image);
    for (const item of view.packages)
      add(item.title, `Explore the ${item.title} package for ${view.name}.`, item.image);
    return candidates.slice(0, 6);
  }, ...ngDevMode ? [{ debugName: "productTourSlides" }] : []);
